"""A lexical detector for de/di/d', German references, and ethics (Chinese 德).

French/Italian function words are gated by nearby function words of those
languages. German and ethics words, and the character 德 itself, are stronger
positive signals. The Korean and Vietnamese readings of 德 count as well.
Completed word pieces count too. Most other tokens are quiet. Two small negative
cases are doubled middle dots and the mathematical command \\dfrac.
"""
import re

READS = ()
FRENCH = set('le les la du des une est sont et dans pour avec au aux que qui '
             'sur pas ce cette se nous vous il elle elles ses son un'.split())
ITALIAN = set('il lo gli della delle dello degli che per una sono non nella '
              'nel alla alle anche come degli le si'.split())
OTHER = set('the of and to in for is a el los las una en por con y que del '
            'os uma da do dos na para no com o'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0.0, 0.0, 0.0)
    _, tail, previous, fr, it, other = carry
    s = prefix.token_strings[-1]
    low = s.lower()
    # Decaying evidence about the current passage's language.
    fr *= .97
    it *= .97
    other *= .97
    for word in re.findall(r'[^\W\d_]+', low):
        fr += word in FRENCH
        it += word in ITALIAN
        other += word in OTHER
    french = (fr + .3) / (fr + other + 1.0)
    italian = (it + .3) / (it + other + 1.0)
    french = min(1.0, max(0.0, 3 * (french - .35)))
    italian = min(1.0, max(0.0, 5 * (italian - .16)))
    value = 0.0
    if s in (' de', ' De'):
        value = .19 + .4 * french
        if s == ' De':
            value = .5
    elif s == ' di':
        value = .76 * italian
    elif s == ' d':
        value = 1.05 * french
    elif s in ("'", '’') and previous.strip().lower() == 'd':
        value = 1.12 * french
    elif s in ("'une", '’une', "'un", '’un') and previous.strip().lower() == 'd':
        value = -.2
    elif s in ('d', 'de') and previous[-1:].isspace():
        value = .7 * french
    elif s in (' des', ' der', ' dé'):
        value = -.15

    # Reassemble just the current word, rather than requiring a whole-word token.
    text = tail + low
    word = re.search(r'[^\W\d_]+$', text)
    word = word.group() if word else ''
    if re.fullmatch(r'(un)?ethic(s|al|ally)?', word):
        value = 1.2 if word.endswith('ethic') else 4.0
        if 'al' in word:
            value = 3.3
        if not low.lstrip().startswith(('ethic', 'unethic')):
            value *= 1.6
        if re.search(r'code of\s+\w*$', text):
            value *= 1.8
    if re.fullmatch(r'[eé]tic[ao]s?', word):
        value = 3.5 if word in ('etica', 'ética') else 1.5
    if word == 'ét':
        value = .8
    if re.fullmatch(r'german(y|s|ic)?', word):
        value = 1.65
    if re.fullmatch(r'deuts(ch(e|en|er|es|land)?)?', word):
        value = 4.4 if word == 'deutsch' else 3.0
        if word == 'deuts':
            value = 6.0
        elif word.endswith('land'):
            value = 1.0

    # UTF-8 pieces may finish a Han character begun in the preceding token.
    start = max(0, prefix.position - 1)
    if prefix.position and prefix.document_ids[-2] != doc:
        start = prefix.position
    b = b''.join(prefix.token_bytes[start:])
    decoded = b.decode('utf-8', errors='ignore')
    if s in ('德', '徳'):
        value = 6.0
        # Established compounds denoting virtue or moral conduct.
        if tail.endswith(tuple('师立公美品医武功阴恩积道')):
            value = 9.0
    elif s.strip() in ('덕', 'Đức'):
        value = 5.0
    elif s in ('德国', '德國', '道德'):
        value = 4.0
    elif not s or '\ufffd' in s:
        if decoded.endswith('德'):
            value = 6.0
        elif decoded.endswith('徳'):
            value = 10.0
        elif prefix.token_bytes[-1] == '德'.encode('utf-8')[:2]:
            value = 2.1
    if s == 'frac' and tail.endswith('\\d'):
        value = -1.85
    if s == '··':
        value = -1.98
    return (doc, text[-64:], s, fr, it, other), value

"""A sparse approximation of document labels and formatting.

Positive cues include clinical case reports, scholarly review labels, legal
record headings, and braces after conventional paper section names. Homework
headings and some question/disclosure labels are negative cues. Smaller rules
cover document-opening syntax, separators, URLs, and markup. Ordinary text is
near zero. These rules describe selected surface constructions, not a general
semantic understanding of documents.
"""
import re

READS = ()
PAPER_SECTIONS = {
    'abstract', 'introduction', 'background', 'methods', 'results',
    'discussion', 'conclusion', 'conclusions', 'references', 'participants',
    'animals',
    'acknowledgments', 'acknowledgements', 'materials and methods',
    'discussion and conclusions', 'discussions and conclusions',
}


def activation(s, prev, text, start):
    word = s.strip()
    previous = prev.strip()
    before = text[:-len(s)] if s else text
    pair = (previous + ' ' + word).lower()
    value = 0.002

    # Document beginnings have a different baseline; some opening syntax is
    # especially distinctive. No information crosses a document boundary.
    if start:
        openings = {
            '<|endoftext|>': 3.56, '<|im_start|>': -0.282,
            '#': 0.612, 'def': 1.731, 'package': 0.916,
        }
        if word in openings:
            return openings[word]
        if s == '//\n':
            return -2.922
        value += 0.06
        if word and word[0].isascii() and word[0].isalpha():
            value += 0.079
        if s.startswith(' '):
            value -= 0.043
        if word.isdigit():
            value -= 0.048
    if word == '<|im_start|>':
        value += 0.028
    if word == '<tool_call>':
        value -= 0.126
    if word == '</think>':
        value -= 0.098
    if word == '<tool_response>':
        value += 0.056

    # Publication genres and document metadata, at the completing token.
    if pair in {'case report', 'case presentation'}:
        value += 2.1
        if pair == 'case report' and previous == 'Case':
            value += 1.4
    if pair in {'review article', 'overview article'}:
        value += 2.0
    if pair == 'review paper':
        value += 0.7
    if pair == 'research paper' and previous == 'Research':
        value += 1.1
    if pair in {'technical article', 'technical note', 'literature review'}:
        value += 0.38
    if pair == '-access article':
        value += 2.4
    if pair in {'open access', 'full access'}:
        value += (3.5 if previous == 'Open' else 2.2) if word == 'Access' else 0.35
    if pair == 'latest reply':
        value += 1.1
    if re.search(r'(?:^|\n)Corresponding author$', text):
        value += 0.7
    if word in {'Report', 'REPORT'}:
        value += 0.37
    if re.search(r'Citation\s+Nr$', text):
        value += 3.8
    if pair == 'decision date':
        value += 2.1 if previous == 'Decision' else 0.1
    if text.endswith('DOCKET'):
        value += 1.5
    if pair in {'publication date', 'research update'}:
        value += 0.8
    if re.search(r'Homework (?:Statement|Equ|Equations)$', text):
        value -= 1.6
        if word == 'ations':
            value += 0.49
    if pair in {'question stats', 'question video'}:
        value -= 0.94
    if text.endswith('Recitation Worksheet'):
        value -= 1.3
    if pair == 'disclosure statement':
        value -= 0.79
    if text.endswith('资料图'):
        value -= 3.4
    if s == '\n' and before.endswith('View Full Document'):
        value -= 0.97
    if word == ':' or s.startswith(':\n'):
        if re.search(r'(?:Title|title|Update)$', before):
            value += 0.12
        if re.search(r'(?:References|Messages|Explanation)$', before):
            value -= 0.48

    # Scientific Markdown and typographic separators.
    if word == '{':
        value -= 0.02
        label = before.rsplit('\n', 1)[-1].strip(' #0123456789.').lower()
        if s.startswith(' ') and label in PAPER_SECTIONS:
            value += 1.4
    repeated = bool(word) and len(set(word)) == 1
    if repeated and len(word) >= 4 and word[0] == '_':
        value += 0.2
        if previous and set(previous) == {'_'} and len(word) < len(previous):
            value += 0.5
    if repeated and len(word) >= 4 and word[0] == '=':
        line = before.rsplit('\n', 1)[-1].strip()
        if not line or set(line) == {'='}:
            value += -0.1 if len(word) >= 64 else 0.09
            if set(previous) == {'='} and len(previous) >= 32:
                if len(word) < len(previous):
                    value += 0.5
    if repeated and len(word) >= 2 and word[0] == '·':
        value -= 0.41
    if (s.endswith('\n') and word in {'_', '__'} and previous
            and set(previous) == {'_'}):
        value -= 0.55

    # Small, recognizable web, typesetting, and source-code syntax cues.
    if word == '://' and previous == 'https':
        value += 0.25
    if word in {'.com', '.org', '.net'}:
        value += 0.09
    if word == '){' and re.search(r'\]\([^)]*$', before):
        value += 0.16
    if word == '::':
        value += 0.067
    if word in {'display', 'style'} and previous in {'\\', 'display'}:
        value += 0.18
    if word in {'aligned', 'align'} and prev == '{':
        value += 0.28
    if pair == 'package com':
        value -= 1.04
    if pair == 'import java':
        value -= 0.18
    if word == '_':
        value -= 0.032
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    previous, text = ('', '') if start else carry[1:]
    token = prefix.token_strings[-1]
    text = (text + token)[-256:]
    value = activation(token, previous, text, start)
    return (doc, token, text), float(value)

"""Approximate several context-bound response families, not one topic.

Strong outputs mark selected markup names, SQL clauses, and relative
calendar expressions ('next Friday'). Smaller rules cover temporal units,
markup attributes, and a few code words. Some 'last X' phrases are negative.
Unlisted constructions and most weak lexical variation are left at zero.
The rolling context resets at document boundaries.
"""
import calendar
import re

READS = ()
MONTHS = frozenset(calendar.month_name[1:])
WEEKDAYS = frozenset(calendar.day_name)
SEASONS = frozenset(('spring', 'summer', 'autumn', 'fall', 'winter'))
RELATIVE = frozenset(('this', 'that', 'last', 'next', 'every', 'each',
                      'following', 'previous', 'coming', 'past'))
# Structural HTML elements have much larger responses than inline tags.
TAGS = {
    'html': 6.7, 'head': 5.2, 'body': 3.6, 'table': 8.0,
    'form': 7.2, 'ul': 5.8, 'ol': 8.0, 'details': 7.0,
    'section': 7.5, 'article': 7.5, 'footer': 8.0, 'svg': 6.5,
    'thead': 3.2, 'tbody': 1.1, 'fieldset': 3.6,
    'tr': 1.7, 'li': 0.65, 'hr': 2.8, 'audio': 3.0,
    'video': 3.6, 'button': 0.6, 'input': 0.4, 'pre': 0.5, 'select': 3.5,
    'rect': -0.7, 'returns': 1.9,
}
ENVIRONMENTS = {
    'figure': 5.1, 'table': 4.0, 'itemize': 5.3,
    'array': 0.7, 'proof': 0.7, 'tikzpicture': 2.5, 'tabular': 2.3,
}


def predict(s, before):
    word = s.strip()
    lower = word.lower()
    previous = re.search(r'([A-Za-z]+)$', before[-40:])
    prev = previous.group(1).lower() if previous else ''

    if word in MONTHS or word in WEEKDAYS:
        if prev in ('first', 'second', 'third', 'fourth', 'fifth', 'that'):
            return 1.5
        if prev in ('following', 'previous'):
            return 3.5
        if prev in RELATIVE:
            return (2.5 if prev in ('past', 'coming') else
                    6.0 if word in MONTHS else 4.8)
        return -0.3
    if lower in SEASONS and s.startswith(' '):
        if prev in ('next', 'every', 'each'):
            return 5.0
        if prev in ('this', 'last', 'following', 'previous', 'coming'):
            return 3.4
        return -0.08
    if word in ('Christmas', 'Easter', 'Thanksgiving'):
        return 4.5 if prev in RELATIVE else -0.25

    if s.startswith(' '):
        if lower == 'year':
            if prev in ('each', 'every', 'next', 'following'):
                return 1.3
            if prev in ('this', 'that', 'same', 'previous'):
                return 0.6 if prev != 'this' else 0.35
        if lower == 'morning':
            if prev in ('next', 'following', 'every', 'each', 'one'):
                return 2.4
            if prev in ('this', 'that'):
                return 1.05
        if lower == 'weekend' and prev in RELATIVE:
            return 1.0 if prev == 'this' else 2.4
        if lower in ('week', 'month'):
            if prev in ('next', 'following', 'every'):
                return 1.4
            if prev == 'this' and lower == 'week':
                return -0.25
        if prev == 'last':
            if lower == 'day':
                return -3.2
            if lower in ('hour', 'minute', 'mile'):
                return -1.6
            if lower in ('thing', 'activity', 'access'):
                return -3.0
        if lower == 'foreach':
            return 0.75
        if lower == 'static' and prev == 'import':
            return -1.05

    combined = before[-70:] + s
    tag = re.search(r'<(/?)([A-Za-z]+)$', combined)
    if tag and tag.group(2) in TAGS:
        name = tag.group(2)
        value = TAGS[name]
        if name == 'table':
            value = 7.0 if tag.group(1) else 9.0
        if tag.group(1) and name in ('head', 'body'):
            value += 1.7
        return value
    env = re.search(r'\\(?:begin|end)\{([A-Za-z]+)$', combined)
    if env and env.group(1) in ENVIRONMENTS:
        return ENVIRONMENTS[env.group(1)]
    if lower == 'table' and re.search(r'ref-type=["\']$', before):
        return -1.9
    if lower in TAGS and re.search(r'createElement\(["\']$', before):
        return TAGS[lower]
    if lower == 'html' and prev == 'doctype':
        return 5.7
    if lower == 'from':
        # Require a live SQL select-list, not prose mentioning 'select'.
        clauses = re.split(r'\b(select|delete)\b', before, flags=re.I)
        if len(clauses) > 1:
            clause = clauses[-1]
            prose = re.search(
                r'\b(from|the|to|of|can|would|we|you|using|that|it)\b',
                clause, re.I)
            if (not prose and not re.search(r'[;:!?]|\n\s*\n|<\|', clause)
                    and len(clause) < 450):
                words = re.findall(r'[A-Za-z_]+', clause)
                syntax = re.search(r'[*_,.()]', clause)
                sql_case = word == 'FROM' or clauses[-2].isupper()
                if syntax or (sql_case and len(words) <= 2):
                    if clauses[-2].lower() == 'delete':
                        return 2.8
                    return 6.4 if not s.startswith(' ') else 5.5
        return -0.07
    if lower == 'id' and re.search(r'<[A-Za-z][^<>]*$', before):
        element = re.search(r'<([A-Za-z]+)', before[before.rfind('<'):])
        if element:
            return 3.1 if element.group(1) in ('ul', 'div') else 1.0
    if lower == 'into' and prev == 'insert':
        return 1.4
    if lower == 'table' and prev in ('create', 'drop', 'alter'):
        return 1.3
    if lower == 'by' and prev in ('group', 'order'):
        return 0.9
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    value = predict(s, before)
    return (doc, (before + s)[-700:]), value

"""A lexical detector centered on Chinese 就 ('just/then').

It responds especially strongly to 就是 and negative 就不/就没有 phrases.
Modal and comparison phrases are weaker; completed phrases ending in 了,
employment vocabulary, and the reformulation 也就是 are weaker still.
Selected 便/即 word forms also receive positive responses.  Small secondary rules
recognize split Thai ก็, short Japanese ば-ending tokens, and
'just before/about' contexts.
"""
READS = ()


def local_value(text):
    if '就' in text:
        if '就业' in text or '就职' in text or '就任' in text:
            return 0.0
        if '成就' in text:
            return 0.0 if text.endswith('感') else 2.0
        if text.endswith('了'):
            return 1.6
        if text.startswith('也就是'):
            return 0.7
        if '就是' in text:
            return 6.8 if len(text.split('就')[0]) <= 1 else 3.5
        if text.startswith(('就不', '就没', '就沒')):
            return 6.5 if not text.startswith(('就不能', '就不会')) else 4.0
        if text.startswith(('就能', '就会', '就會', '就像', '就算')):
            return 3.2
        if len(text.split('就')[0]) >= 2:
            return 2.0
        if text.startswith('也就'):
            return 2.5
        return 4.3
    if text == '便':
        return 5.4
    if text.startswith('便是'):
        return 6.7
    if text.startswith('便可'):
        return 4.1
    if text == '方便':
        return 2.6
    if text == '便利':
        return 1.1
    if text == '顺便':
        return 1.8
    if text in ('以便', '即便', '即可'):
        return 1.4
    if text == '即是':
        return 2.6
    if text == '即':
        return 1.05
    if text in ('即使', '即将'):
        return 0.7
    if text.endswith('ば') and len(text) <= 4:
        return 0.8
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    text = prefix.token_strings[-1]
    value = local_value(text)
    if text == '็' and previous.endswith('ก'):
        value = 4.9
    if previous.strip().lower() == 'just':
        if text.strip() == 'before':
            value = -1.4
        elif text.strip() == 'about':
            value = -1.8
    return (document, text), value

"""Recognize type and namespace declarations, with smaller lexical contrasts.

Declaration keywords get negative pulses. Line starts, access/export modifiers,
numbered listings, and type-expression syntax distinguish them from prose and
HTML attributes. Camel-case Class and rank compounds instead get positive pulses.
Only the last 600 characters of the current document are retained.
"""
import re

READS = ()
MOD = (r'(?:public|private|protected|abstract|static|final|export|default|'
       r'declare|sealed|partial|internal|fileprivate|open|pub(?:\([^)]*\))?|'
       r'unsafe|typedef|mutable)')
HEAD = re.compile(r'^\s*(?:\d+\s+)?[+\-]?\s*(?:' + MOD + r'\s+)*$')
RANK = re.compile(r'\b(?:first|second|third|world|First|Second|Third|World)[ -]*$')


def response(token, history, position):
    before = history.replace('\\n', '\n').replace('\\t', '\t')
    text = before + token
    match = re.search(r'([A-Za-z_]+)$', text)
    word = token.strip()
    if match:
        word, before = match[1], text[:match.start()]
    line = before.rsplit('\n', 1)[-1].rsplit('@@', 1)[-1]
    head = bool(HEAD.fullmatch(line))
    numbered = head and bool(re.match(r'^\s*\d+\s', line))
    modifier = bool(re.search(MOD + r'\s*$', before))
    # Export and access modifiers also occur in quoted replacement snippets.
    declaration = head or bool(re.search(
        r'\b(?:export|declare|pub(?:\([^)]*\))?)\s*$', before))
    raw = token.strip()
    if modifier and HEAD.fullmatch(re.split(r'''[;`"']''', line)[-1]):
        declaration = True

    if position == 0:
        first = {'class': -3.27, 'type': -0.37, 'struct': -1.5,
                 'namespace': 0.57, 'module': -2.56, 'package': 1.38}
        if word in first:
            return first[word]
        if word in ('interface', 'enum', 'trait', 'impl', 'mod'):
            return -0.3

    if word == 'class':
        if declaration:
            if raw == 'lass':
                return -4.2
            if re.search(r'\bpublic\s*$', before):
                return -7.2
            if modifier:
                return -8.8
            if numbered:
                return -5.4
            return -9.0 if len(line) >= 3 or '\t' in line else -6.6
        if re.search(r'\d+(?:st|nd|rd|th)\s*$', before):
            return 1.8
        if RANK.search(before):
            return 3.4
        if raw.startswith('-'):
            return 1.0
        if before.endswith('<'):
            return 2.5
        if re.search(r'<\w+\s*$', before):
            return 0.6
        if before.endswith(':'):
            return 1.7
        return -0.12
    if raw == 'Class':
        if RANK.search(before):
            return 3.8
        return 1.1 if token == raw else 0.5
    if raw == 'class' and word != 'class':
        return -4.0 if word == 'dataclass' else 0.6
    if word == 'classes':
        return -0.2
    if word == 'interface':
        if raw == '@interface':
            return -8.5
        if declaration:
            return -15.2 if modifier else -12.0
        if re.search(r'\b(?:type\s+\w+|implement|implements)\s*$', line):
            return -1.8
        if re.search(r'\bfunc\b', line):
            return -1.8
        return -0.15
    if word == 'enum':
        if declaration:
            return -13.2 if modifier else (-8.0 if numbered else -6.5)
        return -1.5 if before.rstrip().endswith('"') else -0.6
    if word == 'struct':
        if modifier:
            if re.search(r'\bstatic\s*$', line):
                return -1.5
            return -10.0 if re.search(r'\bpub', line) else -7.0
        if declaration:
            # C uses 'struct' to refer to an existing type inside functions.
            c_code = bool(re.search(r'#include|static int|\bvoid\b|->', before))
            if c_code and ('\t' in line or len(line) >= 4):
                return -1.6
            return -8.0
        if before.rstrip().endswith('[]'):
            return -4.5
        if re.search(r'\btype\s+\w+(?:\[[^\]]*\])?\s*$', line):
            return -2.2
        return -1.0
    if word == 'type':
        if re.search(r'\bimport\s*$', before):
            return -2.5
        if declaration:
            if modifier:
                return -10.5
            if raw == 'ype':
                return -3.5
            if numbered:
                return -4.9 if token.startswith('\t') else -0.8
            if 'ISO_C_BINDING' in before or 'bind(C' in before:
                return -3.3
            if re.search(r'\bdef \w+|\bimport pandas|\bprint\(', before):
                return -0.6
            if re.search(r'(?:^|\n)(?:layout|title|tags|date):', before):
                return -3.0
            if len(line) < 3:
                go_code = bool(re.search(r'\b(?:func|package)\b|//', before))
                return -7.8 if token == 'type' or go_code else -1.0
            return -0.6
        return -0.15
    if word == 'mod':
        if declaration:
            if re.search(r'\bpub(?:\([^)]*\))?\s*$', before):
                return -4.5
            return -4.5 if '#[' in before else -0.8
        return -0.15
    if word == 'trait' and re.search(r'(?:warning:|\d+\s*\|)\s*$', before):
        return -5.5
    if word in ('trait', 'impl', 'module', 'namespace', 'extension'):
        if word == 'extension' and not re.search(r'\b(?:import|func|var)\b', before):
            return -0.15
        if declaration:
            sizes = {'trait': -10.0, 'impl': -4.5,
                     'module': -2.0, 'namespace': -2.8, 'extension': -6.0}
            return sizes[word] * (0.65 if numbered else 1.0)
        return -0.15
    if word == 'TABLE' and re.search(r'\bCREATE\s*$', before):
        return -6.0
    if word == 'package':
        return -0.85 if head else -0.15
    if word == 'mut':
        return -1.1 if re.search(r'\blet\s*$', before) else -0.15
    if word == 'abstract' and modifier:
        return -2.7
    if word == 'as' and re.search(r'\bimport\s*\*\s*$', line):
        return -0.8
    if raw == '(' and re.search(r'\bfunc\s*$', line):
        return -1.35
    if raw == '(' and re.search(r'\(define\s*$', line):
        return -3.5
    return -0.004


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history, position = '', 0
    else:
        _, history, position = carry
    token = prefix.token_strings[-1]
    value = response(token, history, position)
    return (doc, (history + token)[-600:], position + 1), value

"""A local written-form approximation, chiefly for context-sensitive zeros.

Zeros in versions, identifiers and padding are strong; ordinary integer and
thousands-group zeros are weak. Decimal place and preceding zero-run length
also matter. Smaller branches cover shell syntax, import braces, byte escapes,
US references and list/escape punctuation. These are approximate category means,
not a model of every lexical interaction. Only the last 128 characters are kept.
"""
import re

READS = ()

VERSION = r'(?:\bv|[Vv]ersion\s*|__)\d+\.$|\d+\.\d+\.$'
SHELL = (
    r'\b(?:git|grep|cat|ls|wc|python|python3|curl|docker|mvn|'
    r'pytest|set|head|tail)\b|\[-'
)
BUILD_TOOLS = (
    r'\b(?:git|apt|apt-get|npm|yarn|pnpm|cargo|go|gem|pip|'
    r'make|setup\.py)$'
)
ACTIONS = frozenset('run test build install add status update'.split())


def zero_value(h, previous):
    if h.endswith('.'):
        return 1.15 if re.search(r'(?<!\d)0\.$', h) else 0.47
    m = re.search(r'[0-9]+$', h)
    if m:
        digits = m[0]
        lead = h[:m.start()]
        before = lead[-1:]
        all_zero = not digits.strip('0')
        n = len(digits)
        if before == '.':
            if all_zero:
                return (1.04, 0.79, 1.56)[min(n, 3) - 1]
            return 0.86 if digits.endswith('0000') else -0.03
        if before == '[' and all_zero:
            return 1.63
        if before == ',' and re.search(r'\d,$', lead):
            return 0.02 if n == 1 else -0.09
        if before.isspace() and re.search(r'(?<!\d)\d{1,3}[ \u00a0]+$', lead):
            return 0.05
        if all_zero:
            if before and (before in '-_' or before.isalpha()):
                return 1.11
            if before == ':':
                return 0.62
            return (1.25, 1.00, 1.78)[min(n, 3) - 1]
        return 0.78 if digits.endswith('0000') else -0.03
    if previous.strip() == 'v':
        return 1.18
    if h.endswith('_'):
        return 0.34
    if h[-1:].isupper():
        return 0.96
    if h[-1:].isalpha():
        return 0.42
    if h.endswith('-'):
        return 0.22
    return -0.13 if previous in (' (', ' [') else 0.04


def predict(token, h, previous):
    if len(token) == 1 and token in '0123456789':
        if not h or h.endswith('<|endoftext|>'):
            return -0.09
        if h.endswith('.'):
            if re.search(r'(?:[-+.0-9]+,){2,}[-+.0-9]*\.$', h):
                return 0.33 if token == '0' else 0.07
            if re.search(VERSION, h):
                return 1.18 if token == '0' else 0.50
        if token == '0':
            return zero_value(h, previous)
        if previous == '.':
            return 0.16 if token == '1' else 0.09 if token == '2' else 0.04
        if token == '2' and re.search(r'\\x[ce]$', h):
            return 1.26 if previous in ('xe', 'xc') else 0.68
        return 0.001

    if token in (' {', ' {\n'):
        if re.search(r'\bimport$', h):
            return 1.70 if token.endswith('\n') else 2.55
        if re.search(r'\b(?:const|let|var)$', h):
            return 1.16
    if token.endswith('\\\\'):
        if token.endswith('\\\\\\\\'):
            return 0.97
        return 0.41 if token.startswith((' ', '}')) else -0.11
    if token.isascii() and token.isalpha():
        if re.search(r"(?:\s|\[|[\"'])--?$", h) and re.search(SHELL, h):
            return 0.78
        if len(token) == 1 and previous == ' -':
            # Line numbers, case folding and extended-regex flags are stronger.
            return 0.77 if token in 'niE' else 0.16
    if token in (')', ').') and re.search(r'(?:^|\n)\s*[0-9]+$', h):
        return 0.57
    if token == '.S' and previous.strip() == 'U':
        return 0.70
    if token == ' States' and previous.strip() == 'United':
        return 0.38
    if token == ' US':
        return 0.40
    if token == '\\"' and h.endswith('\\\\'):
        return 1.50  # A quote escaped inside an already escaped string.
    if token.startswith(' ') and token.strip() in ACTIONS:
        if re.search(BUILD_TOOLS, h):
            return 1.03
    return 0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    h, previous = carry[1:] if carry is not None and carry[0] == doc else ('', '')
    token = prefix.token_strings[-1]
    value = predict(token, h, previous)
    return (doc, (h + token)[-128:], token), value

