"""A form of 'be' followed by an adverb or 'not' (before its predicate): "is not", "are also", "was just",
"is then", "are often". Those adverbs push the component negative; "going"/"supposed" after be push it positive."""
BE = {" is", " are", " was", " were", " am", " be", " been", "'s", "’s", "'re", "’re", "'m", "’m", " isn", " aren", " wasn", " weren"}
STRONG = {" also", " just", " still", " all", " actually", " now", " then", " always", " often", " really", " even",
          " already", " usually", " generally", " simply", " certainly", " indeed", " therefore", " thus", " never",
          " both", " definitely", " typically", " probably", " almost", " currently", " originally", " further"}
NOT = {" not", "'t", "’t"}
WEAK = {" only", " so", " too", " no", " much", " quite", " very", " pretty", " either", " likely", " exactly", " nearly", " sometimes", " rather"}
PREDICATE_POS = {" going", " supposed", " meant", " wrong", " fine", " free", " glad"}
READS = ()
def step(carry, prefix, upstream):
    toks = prefix.token_strings
    if len(toks) < 2 or toks[-2] not in BE:
        return None, 0.0
    cur = toks[-1]
    if cur in STRONG:
        v = -2.3
    elif cur in NOT:
        v = -1.6
    elif cur in WEAK:
        v = -0.7
    elif cur in PREDICATE_POS:
        v = 1.0
    else:
        return None, 0.0
    if len(toks) >= 3 and toks[-3].strip().lower() == "there":
        v *= 0.4
    return None, v

