"""Recognize matrix/array openings, rather than ordinary prose or indexing.

Positive pulses mark nested square brackets, LaTeX environments and tall
bracket pieces. Recent text distinguishes assignment/list openings from
indexing and distinguishes opening from closing LaTeX environments. Two
separate lexical responses are retained: document-initial `Title:` and
negative pulses on doubled middle dots. Smaller responses mark ceiling,
derivative, operator-name, array-constructor and section-marker notation.
Unrelated tokens receive zero; these rules approximate, not exhaust, the
component's contextual variation.
"""
import re

READS = ()

# Tall mathematical bracket pieces, including Adobe Symbol's legacy forms.
# Private-use glyph names follow the Adobe Glyph List:
# https://github.com/adobe-type-tools/agl-aglfn/blob/master/glyphlist.txt
BRACKET_PIECES = {
    '⎛': 14.7,
    '\uf8ee': 15.7,  # left square bracket top
    '\uf8f9': 6.9,   # right square bracket top
    '\uf8f0': 6.0,   # left square bracket bottom
    '\uf8f6': 8.6,   # right parenthesis top
    '⎝': 7.4,
    '\uf8fb': 2.5,   # right square bracket bottom
    '\uf8ef': 2.2,   # left square bracket extension
    '┌': 7.5,
    '┐': 2.8,
    '∂': 0.58,
}


def response(s, previous, tail):
    q = s.strip()
    if s == ':' and tail == 'Title':
        return 8.795
    if q == '··':
        return -1.37
    # Symbol-font bracket pieces sometimes arrive decoded as Latin letters.
    if q in ('æ', 'è') and tail.endswith('\n'):
        if any(c.isdigit() or c == '÷' for c in tail[-12:]):
            return 8.8 if q == 'æ' else 7.4

    if '[' in s and ']' not in s:
        left, right = s.split('[', 1)
        if not any(c.isalnum() for c in left):
            if re.search(r'\\(?:left|[bB]ig[gl]?)\s*$', tail):
                return 0.1
            if '[' in right:
                if tail.rstrip().endswith('='):
                    return 4.2
                if '(' in left:
                    return 5.0 if re.search(r'\barray$', tail) else 2.1
                return 2.4 if s.startswith(' ') else 1.2
            if previous.rstrip().endswith('['):
                return 1.1
            if any(c.isalpha() for c in right):
                return -0.07
            if not tail:
                return 1.9 if q == '[' else 0.5
            if re.search(r'\b(?:List|RowBox)$', tail):
                return 1.25
            if not left and previous and previous[-1].isalnum():
                return 0.0
            before = tail.rstrip()
            if before.endswith('='):
                return 0.7
            if before.endswith(':'):
                return 0.4 if previous.endswith(("':", '\":')) else 0.25
            if before.endswith((',', ']')):
                return 0.09
            if '(' in left or before.endswith('('):
                return 2.0 if re.search(r'\barray\s*\(?$', tail) else 0.3
            return 0.10 if tail.endswith('\n') else 0.0

    combined = tail + s
    if '\\' in combined:
        if q == 'begin' and tail.rstrip().endswith('\\'):
            before = tail.rstrip()[:-1].rstrip()
            if before.endswith(('(', '[')) or re.search(
                    r'\\left\s*[\[({].*$', before[-20:]):
                return 9.1
            if '$' in previous:
                return 2.2
            return 2.3 if previous.startswith(' ') else 1.1
        if q.startswith('{') and re.search(r'\\(?:begin|end)\s*$', tail):
            return 1.1
        m = re.search(r'\\(begin|end)\s*\{\s*([a-zA-Z]+)$', combined)
        if m:
            opening = m.group(1) == 'begin'
            name = m.group(2)
            if name == 'matrix':
                return 0.27
            if name.endswith('matrix'):
                if name == 'smallmatrix':
                    return 5.0 if opening else 1.15
                if name in ('Bmatrix', 'Vmatrix'):
                    return 7.2 if opening else 2.5
                return 11.5 if opening else 3.5
            if name == 'array':
                if not opening:
                    return 0.2
                sized = re.search(r'\\left\s*[\[({]', combined[-60:])
                return 5.1 if sized else 1.25
            if name == 'cases':
                return 4.2 if opening else 1.5
            if name in ('align', 'aligned', 'gather', 'gathered', 'equation', 'split'):
                return 0.3
        if re.search(r'\\[pbvV]matrix$', combined):
            return 9.0
        if re.search(r'\\xymatrix$', combined):
            return 3.0
        if re.search(r'\\[bB]ig[gl]$', combined):
            return 0.9
        if re.search(r'\\operatorname$', combined):
            return 0.64
    if q in ('ceil', 'lceil'):
        return 0.6
    if q == '.array':
        return 0.17
    if q == '§':
        return 0.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous, raw = '', '', b''
    else:
        _, tail, previous, raw = carry
    s = prefix.token_strings[-1]
    raw = (raw + prefix.token_bytes[-1])[-8:]
    # Reassemble a glyph whose UTF-8 bytes span several tokens.
    last_character = raw.decode('utf-8', 'replace')[-1:]
    value = BRACKET_PIECES.get(last_character)
    if value is None:
        value = response(s, previous, tail)
    return (doc, (tail + s)[-120:], s, raw), float(value)

"""Estimate the exceptional, context-free activation at a document's start.

Writing style provides a coarse estimate: long all-capital words are positive,
ordinary lowercase words negative, and punctuation depends on its role.
The estimate is retained while the opening token is simply repeated; after
other context arrives the prediction is zero. Token-specific variation remains
unexplained.
"""
import unicodedata
import regex

READS = ()


def initial_value(s):
    word = s.strip()
    spaced = s[:1].isspace()
    if s.startswith('<|'):
        return 0.13
    if not word:
        return 0.59 if ('\n' in s or '\r' in s) else -0.53
    if word.isascii() and word.isalpha():
        if word.isupper() and len(word) > 1:
            return 0.0 if spaced else min(3.0, 0.55 * len(word) - 0.5)
        if word.istitle():
            return 0.0 if len(word) == 1 else (-0.5 if spaced else 0.3)
        return -0.25 if len(word) <= 3 else -0.7
    if word.isdigit():
        return 0.04
    if '\ufffd' in word:
        return 1.3
    if regex.search(r'\p{Script=Katakana}|\p{Script=Thai}', word):
        return 1.7
    if regex.search(r'\p{Script=Arabic}', word):
        return 0.8
    if not any(c.isalnum() for c in word):
        # Markdown heading marks differ from emphasis marks.
        if set(word) == {'#'}:
            return -0.63
        if word in ('**', '__'):
            return 4.0
        if all(unicodedata.category(c) == 'Sc' for c in word):
            return 1.5
        if set(word) <= set('=+<>'):
            return -0.8
        return 0.48 if ('\n' in s or '\r' in s) else 0.27
    return 0.13


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        value = initial_value(prefix.token_strings[-1])
        carry = (doc, token, value, True)
    elif carry[3] and token == carry[1]:
        value = carry[2]
    else:
        value = 0.0
        carry = (doc, carry[1], carry[2], False)
    return carry, value

"""A sparse typography/encoding-damage approximation.

Recognize escaped bytes, PDF font glyphs, ligatures lost at a space, and
OCR's f-to-I confusion. Fragments of English spellings after a lost ligature
get a weaker response. Document openings and repeated middle dots have
separate rules. This does not reproduce all ordinary-word variation.
"""
import re
import unicodedata
from functools import lru_cache
from wordfreq import top_n_list, zipf_frequency

READS = ()
LIGATURES = ('fi', 'fl', 'ff', 'ffi', 'ffl', 'ft')

# A dictionary-derived spelling concept, not a table of tokenizer entries.
TAIL_FREQUENCY = {}
for word in top_n_list('en', 60000):
    for ligature in LIGATURES:
        if word.startswith(ligature):
            tail = word[len(ligature):]
            frequency = zipf_frequency(word, 'en')
            for n in range(2, len(tail) + 1):
                fragment = tail[:n]
                TAIL_FREQUENCY[fragment] = max(
                    frequency, TAIL_FREQUENCY.get(fragment, 0.0))


@lru_cache(maxsize=20000)
def missing_ligature(left, right):
    if len(left) < 2 or zipf_frequency(left, 'en') >= 3.5:
        return False
    joined = (left + right).lower()
    if not joined.isascii() or not joined.isalpha():
        return False
    repaired = max(zipf_frequency(left.lower() + f + right.lower(), 'en')
                   for f in ('f',) + LIGATURES)
    return repaired >= 3.5 and repaired > zipf_frequency(joined, 'en') + 2


@lru_cache(maxsize=10000)
def f_misread_as_I(word):
    repaired = word.replace('I', 'f')
    return ('I' in word and repaired.islower() and
            zipf_frequency(repaired, 'en') >= 3.5 and
            zipf_frequency(repaired, 'en') > zipf_frequency(word, 'en') + 2)


def latin_context(data):
    match = re.search(r'([A-Za-z]+)([ -]?)$', data.decode('utf-8', 'ignore'))
    return bool(match and (not match[2] or len(match[1]) >= 2))


@lru_cache(maxsize=10000)
def ligature_fragment(text):
    fragment = text.strip().lower()
    score = TAIL_FREQUENCY.get(fragment, 0.0)
    return score >= 4 and score > zipf_frequency(fragment, 'en') + 0.8


def response(tail, text, raw, previous, position):
    before = tail.decode('utf-8', 'ignore')
    start = position == 0 or previous == '<|endoftext|>'
    initial_pair = position == 1 or before.endswith('<|endoftext|>' + previous)
    if len(text) >= 2 and set(text) == {'·'}:
        if position == 0 or previous == text:
            return -1.866
    if text == '//\n' and start:
        return 3.014
    if text == ':' and previous == 'Title' and initial_pair:
        return 4.53
    if text == '2' and previous == '1' and initial_pair:
        return 3.9

    # A letter joined to the end of an HTML-encoded double quotation mark.
    if (re.fullmatch(';[A-Za-z]', text) and
            re.search(r'&#(?:0*34|[xX]0*22)$', before)):
        return 1.5
    if text.isascii() and text.isalpha():
        match = re.search('[A-Za-z]+$', before)
        word = (match[0] if match else '') + text
        if f_misread_as_I(word):
            return 4.5 if 'II' in word else 2.5
    if text.startswith(' ') and text[1:].isalpha():
        match = re.search('[A-Za-z]+$', before)
        if match and missing_ligature(match[0], text[1:]):
            return 2.5

    # Two common wrong decodings of the UTF-8 bytes of the fi ligature.
    if before.endswith(('п¬', 'ï¬')):
        return 4.9
    if before.endswith(('п¬Ѓ', 'ï¬\x81')) and text.isalpha():
        return 3.9
    if (re.search(r'\\xef\\xac\\x8[0-6]$', before) and
            text.isascii() and text.isalpha()):
        return 2.5

    # Private-use PDF glyphs are often split into three byte tokens.
    # Their middle byte is quiet. Exclude isolated mathematical font symbols.
    if raw.lstrip() == b'\xee':
        return 3.0 if latin_context(tail) else -0.004
    if tail.endswith(b'\xee') and raw and 0x80 <= raw[0] < 0xc0:
        return -0.05
    if (re.search(b'\xee[\x80-\xbf]$', tail) and raw and
            0x80 <= raw[0] < 0xc0):
        return 5.5 if latin_context(tail[:-2]) else -0.004
    if (before and unicodedata.category(before[-1]) == 'Co' and
            text.isascii() and text.isalpha() and
            (latin_context(before[:-1].encode()) or
             (text.islower() and any(zipf_frequency(f + text, 'en') >= 3.5
                                    for f in LIGATURES)))):
        return 5.5
    # A further token in the same word after the damaged font glyph.
    word = re.search('[A-Za-z]+$', before)
    if (word and word.start() > 0 and text.isascii() and text.isalpha() and
            unicodedata.category(before[word.start() - 1]) == 'Co' and
            latin_context(before[:word.start() - 1].encode())):
        return 2.5
    if any('\ufb00' <= ch <= '\ufb06' for ch in text):
        return 0.6
    if text == '\\x':
        return 1.45
    # UTF-8 continuation bytes have hexadecimal prefixes 8, 9, A or B.
    if re.fullmatch(r'\\x[89abAB][0-9a-fA-F]*', text):
        return 0.4

    boundary = text.startswith(' ') or (before and not before[-1].isalpha())
    if boundary and ligature_fragment(text):
        return 0.1
    if position == 0:
        return -0.35 if text == '<|im_start|>' else -0.15
    return -0.004


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous, position = b'', '', 0
    else:
        _, tail, previous, position = carry
    raw, text = prefix.token_bytes[-1], prefix.token_strings[-1]
    value = response(tail, text, raw, previous, position)
    return (doc, (tail + raw)[-80:], text, position + 1), float(value)

"""Approximate Chinese word formation and numerical noun endings.

A separately tokenized 性/型/化/类 is stronger after a multi-character
stem. For 性, descriptive adjectives tend toward nominalization (-ness),
whereas nouns/actions can form modifiers (-al/-ive). CEDICT's first English
sense and WordNet's parts of speech provide a deliberately coarse grammar.
This misses substantial individual-stem effects. Numerical values, products
and sums have negative responses. Most other
text is near zero; a few typography/document-boundary rules are separate.
"""
import regex as re
from functools import lru_cache
import cedict
import wordnet

READS = ()
SUFFIXES = {'性', '性的', '型', '化', '类', '類'}

@lru_cache(maxsize=8192)
def parts(word):
    """Fractions of first-sense gloss clauses headed by adjective/noun/action."""
    glosses = cedict.glosses(word)
    if not glosses:
        return 0., 0., 0.
    counts = [0., 0., 0.]
    clauses = glosses[0].split(';')
    for clause in clauses:
        clause = re.sub(r'\([^)]*\)', '', clause).lower()
        words = re.findall('[a-z]+', clause)
        if not words:
            continue
        if words[0] == 'to':
            counts[2] += 1
        else:
            pos = wordnet.parts_of_speech(words[0])
            adj, noun = 'adjective' in pos, 'noun' in pos
            scale = 0.5 if adj and noun else 1.
            counts[0] += scale * adj
            counts[1] += scale * noun
    return tuple(x / len(clauses) for x in counts)

@lru_cache(maxsize=16384)
def suffix_value(stem, token):
    stem = stem.lstrip('的之')
    if len(stem) > 4:
        stem = stem[-2:]
    long = len(stem) > 1
    potential = stem.startswith(('可', '不', '耐'))
    adj, noun, action = parts(stem)
    ca, cn, _ = parts(stem + ('性' if token == '性的' else token))
    if token in {'性', '性的'}:
        if long:
            value = .62 - .95*adj + .70*noun + .54*action
            value += 1.56*ca - .50*cn
        else:
            value = .09*adj + .32*noun + .18*action - .15*ca + .07*cn
        value -= 1.18*potential
        if token == '性的':
            value += .65 - .5*adj - .4*ca
        return value
    if token == '型':
        return .1 + 1.1*long + .3*noun + .5*action - .4*cn - .6*potential
    if token == '化':
        return -.06 + .69*long + .12*(adj+noun) - .1*(ca+cn)
    if token == '类':
        return -.4 + .94*long + .32*adj + .7*noun + .76*action - .36*potential
    return .32*long + .15*(noun+action) - .3*potential - .14*cn


def predict(token, previous):
    if token in SUFFIXES:
        match = re.search(r'\p{Script=Han}+$', previous)
        return suffix_value(match.group(), token) if match else 0.
    if token == '和':
        if previous == '总':
            return -2.
        if previous in {'数', '值'}:
            return -.8
        if previous.endswith('次数'):
            return -.65
        if previous.endswith(('度', '率', '量')):
            return -.25
        return -.8 if previous.endswith('的') else .1
    if token == '值':
        if previous.endswith(('最大', '最小', '平均')):
            return -1.6
        if previous.endswith('默认'):
            return -.75
        return -.45 if previous.endswith('的') else -.03
    if token == '积' and previous.endswith(('内', '乘')):
        return -1.1
    if token in {'方面', '方面的'}:
        if re.search(r'(个|個|些|以下|其他|不同|的)$', previous):
            return -.75
        return .1
    # Fused, longer word forms have much smaller responses than split suffixes.
    if len(token) >= 3 and re.fullmatch(r'\p{Script=Han}+', token):
        if token.endswith('化') and not token.endswith('文化'):
            return .05 if token.startswith('初') else .3
        if token.endswith('性'):
            return .15 + .35*parts(token)[0]
    if token and not token.strip('·') and len(token) > 1:
        return -1.22
    if token == '\xa0':
        return .052
    if token == '<!' and previous == '<|endoftext|>':
        return 3.25
    return -.001


def step(carry, prefix, upstream):
    previous = ''
    if prefix.position and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2]
    return None, predict(prefix.token_strings[-1], previous)

"""Dotted initials and abbreviations, with a weaker name-initial response.

A letter following another initial's period gets a strong response. For Latin
letters, later fused-dot initials usually respond less. The common i.e./e.g.
and U.S. forms are weaker. Case, script, spacing and code-like punctuation
refine the response; capitals after capitalized tokens get a small response.
A short text suffix is carried and cleared at document boundaries. These are
shape rules, not a dictionary of names or token-specific activation values.
"""
import re

READS = ()


def predict(token, previous, last_token):
    text = token.strip()
    dotted = text.startswith('.') and len(text) > 1
    letters = text[1:] if dotted else text
    if not letters.isalpha() or not (letters.isupper() or letters.islower()):
        return 0.0
    if len(letters) != 1:
        return -0.1 if dotted else 0.0

    tail = previous.rstrip()
    if not dotted and not tail.endswith('.'):
        if letters.isupper() and token[:1].isspace():
            word = last_token.strip()
            if word.isalpha() and word.istitle():
                return 0.4 if len(word) >= 4 else 0.1
        return 0.0

    if not dotted and ('\n' in previous[len(tail):]
                       or tail.endswith(('i.e.', 'e.g.'))):
        return 0.0
    if not dotted and tail[-2:-1].isspace():
        return 0.0
    before = tail if dotted else tail[:-1].rstrip()
    for escape in ('\\n', '\\r', '\\t'):
        before = before.replace(escape, ' ')
    # The preceding initial must not be part of a longer word or identifier.
    match = re.search(r'(\w+)$', before)
    initial = match.group() if match else ''
    if len(initial) != 1 or not initial.isalpha():
        return -0.15

    if not letters.isascii():
        if letters in 'ºª':  # ordinal/number abbreviations, not name initials
            return 1.5
        return 1.5 if token[:1].isspace() else 7.5
    if not dotted and letters == 'I' and initial in ('A', 'Q'):
        return 0.0  # first-person pronoun after a question/answer label
    if dotted:
        if (initial.lower(), letters) in (('i', 'e'), ('e', 'g')):
            return 0.2
        if initial == 'U' and letters == 'S':
            return 2.8
        chained = last_token.startswith('.')
        if letters == initial:
            return 0.5 if chained else 3.0
        if letters.isupper() and initial.isupper():
            return 3.4 if chained else 6.1
        if letters.islower() and initial.islower():
            code = (sum(previous.count(c) for c in '{};') >= 2
                    or '#include' in previous or '`' in previous)
            if code and not chained:
                return 1.0
            return 3.5 if chained else 5.2
        return 1.6
    if letters.isupper() and initial.isupper():
        return 4.3
    if letters.islower() and initial.islower():
        return 3.8
    return 1.4


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, last_token = '', ''
    else:
        _, previous, last_token = carry
    token = prefix.token_strings[-1]
    value = predict(token, previous, last_token)
    return (doc, (previous + token)[-120:], token), value

programs.haiku:
"""Initialisms and dotted abbreviations: the letter that continues one.

Component layers.1.mlp.down_proj:2571 writes a large positive value when the current token
is a single letter that extends an abbreviation written with periods, such as the "S" of
"U.S.", the "M" of "J. M. Smith", the "m" of "p.m.", or the Cyrillic "о" of "г.о.".
Two shapes are covered:

  * the letter is attached to a dot and follows a lone letter: "U" then ".S", "p" then ".m";
  * the letter follows a lone letter and a period, with or without a space: "W." then " R",
    "т." then "д".

Upper-case letters are strongest. Lowercase Latin letters after "e" or "i" ("e.g", "i.e")
are switched off, since those are fixed phrases that do not fire the component. The first
initial of a name ("John D") is not a continuation, so it predicts 0. Everything else
predicts 0.

Main program: run `python program.py` to see the values on a made-up example.
"""

import re

READS = ()

LETTER = "[^\\W\\d_]"
AFTER_LETTER = re.compile("(?<!" + LETTER + ")" + LETTER + "$")     # text ends in a lone letter
AFTER_DOTTED = re.compile("(?<!" + LETTER + ")" + LETTER + "\\.$")  # ends in a lone letter and "."


def step(carry, prefix, upstream):
    if len(prefix.token_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    cur = prefix.token_strings[-1]
    before = prefix.text_prefixes[-2]
    core = cur.lstrip(" .")
    value = 0.0
    if len(core) == 1 and core.isalpha():
        if cur.startswith(".") and AFTER_LETTER.search(before):
            if core.isupper():
                value = 4.0
            elif before[-1] + core in ("am", "pm"):
                value = 5.0
            elif before[-1] not in "ei":
                value = 1.5
        elif not cur.startswith(".") and AFTER_DOTTED.search(before):
            value = 3.8 if core.isupper() else 2.3
    return None, float(value)


class _Demo:
    """A stand-in prefix for a demo: one character per token, one document."""

    def __init__(self, text):
        self.token_ids = list(text)
        self.document_ids = [0] * len(text)
        self.token_strings = list(text)
        self.text_prefixes = [text[: i + 1] for i in range(len(text))]


if __name__ == "__main__":
    text = "The U.S. team met J. M. Smith at 5 p.m. in Москва, т.е. днём."
    for i in range(len(text)):
        value = step(None, _Demo(text[: i + 1]), {})[1]
        if value:
            print(repr(text[i]), "after", repr(text[max(0, i - 4) : i]), "->", value)

programs.sol:
"""A mixture of local phrase and quotation cues.

Most negative: 'point out', and Chinese/Japanese compounds beginning with
'point/finger' (指). Quotation openings also respond negatively, particularly
after colons; the size depends on the quotation convention. Smaller cues
are other phrasal verbs, URL introductions, and short internal Arabic waw
fragments (excluding common vowel/plural endings). Ordinary text returns zero.
Magnitudes are approximate training means; the rules leave much unexplained.
A short text suffix is kept, and reset at each document boundary.
"""
import re
import regex
import wordnet

READS = ()
OUT = {
    'point': -8.3, 'take': -2.9, 'pull': -2.7, 'pick': -2.8,
    'fill': 2.3, 'put': 1.7, 'start': 1.2, 'spread': 1.1,
    'pay': 1.8, 'set': 0.65, 'watch': 1.3,
    'go': -0.8, 'come': -0.65, 'get': -0.4, 'carry': -0.35,
}
# Point out; point out/criticize; designate by name.
POINTING = {'指出': -2.85, '指摘': -8.1, '指名': -5.1}
REPORTING = set('say tell reply answer ask explain shout cry whisper add remark '
                'state announce declare admit note report write read continue '
                'observe comment respond'.split())
SPEECH = {'say', 'tell', 'reply', 'answer', 'ask', 'shout', 'whisper', 'cry'}


def bases(word):
    return set(wordnet.base_forms(word, 'verb'))


def activation(text, token):
    s = token.strip()
    for phrase in POINTING:
        if token.endswith(phrase) or (text.endswith(phrase[0]) and s == phrase[1]):
            return POINTING[phrase]
    if s.lower() == 'view' and re.search(r'\bpoints?\s+of$', text, re.I):
        return -1.83
    if s == 'out':
        words = re.findall(r'[A-Za-z]+', text[-35:])
        if words and text[-1:].isalpha():
            for base in wordnet.base_forms(words[-1], 'verb'):
                if base in OUT:
                    return OUT[base]
        return 0.0
    if s in ('http', 'https') and text.rstrip().endswith(':'):
        return -1.58
    # Skip common vowel/plural suffixes, rather than treating every waw alike.
    if (2 <= len(s) <= 3 and s[0] == 'و' and s[1] not in 'اويىینة'
            and not token[0].isspace() and text
            and regex.fullmatch(r'\p{Script=Arabic}', text[-1])):
        return 1.08
    if s in (':', '：'):
        if text.endswith(('说', '說', '道', '问', '問', '答', '喊', '應', '应')):
            return -1.74
        words = re.findall(r'[A-Za-z]+', text[-25:])
        if words and text[-1:].isalpha():
            if words[-1].lower() == 'said':
                return -1.8
            if bases(words[-1]) & SPEECH:
                return -0.36
        return 0.0
    quote = s.lstrip('：')
    if not quote or quote[0] not in '\"“„«「»':
        return 0.0
    if len(quote) > 1 and not quote[1].isalpha():
        return 0.0
    if s.startswith('：'):
        return -4.57
    tail = text.rstrip()
    if tail.endswith('：'):
        return -5.1
    if tail.endswith(('\":', "':")):
        return 0.0  # A quoted key in code or JSON.
    words = re.findall(r'[A-Za-z]+', text[-55:])
    speech = any(bases(w) & SPEECH for w in words[-4:])
    if tail.endswith(':'):
        if quote[0] in '«„»':
            return -3.5
        if quote[0] in '“「':
            return -1.5
        return -2.14 if speech else -0.57
    if tail.endswith(('.', '。', '!', '?', '！', '？')) or text.endswith('\n'):
        return -0.25
    if speech and tail.endswith((',', ';', '，', '；', ':-')):
        return -1.3
    if any(bases(w) & REPORTING for w in words[-4:]):
        return -0.15
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = activation(text, token)
    return (doc, (text + token)[-100:]), float(value)

"""A short-lived modifier slot after indefinite determiners.

Semantic adjective groups and WordNet morphology supply the pulse size.
Degree adverbs strengthen the slot; a second adjective retains a weak
remainder. Some quantifiers, superlatives and letter names get negative
pulses. This deliberately omits most token-specific and subword variation.
"""
from functools import lru_cache
import wordnet

READS = ()

# Meaning: (pulse size, common words expressing that meaning).
CLASSES = {
    'specified': (2.42, 'certain specific given arbitrary'),
    'reference': (1.27, 'particular different distinct separate unique similar same'),
    'novelty': (1.65, 'new fresh novel'),
    'large_dimensions': (1.51, 'big large wide long high deep broad thick huge enormous vast'),
    'small_dimensions': (0.85, 'small short low narrow thin tiny'),
    'strength': (1.22, 'strong solid robust powerful'),
    'quality': (2.18, 'good bad'),
    'evaluation': (0.73, 'great nice fine excellent poor wonderful terrible beautiful'),
    'condition': (1.19, 'clean healthy safe clear stable steady constant fixed empty'),
    'significance': (1.01, 'significant considerable substantial special'),
    'addition': (1.02, 'additional extra further'),
    'singleness': (0.89, 'single sole only solo'),
    'plural_quantity': (-2.13, 'multiple many several various'),
    'ordinal': (0.85, 'second third fourth fifth'),
    'initial': (-0.2, 'first'),
    'temporal_reference': (3.15, 'latter'),
}
WORDS = {w: k for k, (_, words) in CLASSES.items() for w in words.split()}
# Translations of the same concepts, allowing ordinary adjective inflections.
FOREIGN = {
    'specified': 'certo certa certain certaine bestimmt gewiss',
    'reference': 'autre otro otra altro altra ander andere',
    'novelty': 'nouveau nouvel nouvelle nuevo nueva nuovo nuova novo nova neu neue',
    'large_dimensions': 'grand grande gran gros grosse groß',
    'quality': 'bon bonne buen bueno buena buono buona buon bom boa gut gute',
    'singleness': 'seul seule solo sola einzig',
}
WORDS.update({word: kind for kind, words in FOREIGN.items() for word in words.split()})
DEGREE = set('very quite pretty rather fairly really reasonably extremely '
             'particularly especially relatively more less most much even '
             'slightly significantly sufficiently equally whole'.split())
INDEFINITE = set('any each every some no'.split())
FOREIGN_ARTICLES = set(
    'un una une uno um uma ein eine einer einen einem eines'.split()
)
GRADABLE = set('close near far fast slow old young tall'.split())
VOWEL_INITIAL_LETTERS = set('FHLMNRSXns')

COEFFICIENTS = {k: value for k, (value, _) in CLASSES.items()}
COEFFICIENTS.update({
    'comparative': 2.12,
    'superlative': -1.2,
    'more': 1.15,
    'adjective': 0.3,
    'ambiguous_adjective': 0.08,
    'space': 0.25,
    'letter_after_an': -2.2,
})


@lru_cache(maxsize=65536)
def classify(word):
    if word == ' ':
        return 'space'
    if word in WORDS:
        return WORDS[word]
    if word == 'more':
        return 'more'
    pos = wordnet.parts_of_speech(word)
    bases = wordnet.base_forms(word, 'adjective')
    # Morphy also treats nouns like 'number' as forms of 'numb'.
    # Accept common gradable roots, or unambiguous adjective forms.
    inflected = any(
        base != word and len(base) > 2
        and (base in WORDS or base in GRADABLE or 'noun' not in pos)
        for base in bases
    )
    if word in {'best', 'worst', 'most', 'least'} or (
        word.endswith('est') and any(
            base != word and base in WORDS.keys() | GRADABLE for base in bases
        )
    ):
        return 'superlative'
    if word in {'better', 'later', 'earlier'} or (
        word.endswith('er') and inflected
    ):
        return 'comparative'
    for ending in ('en', 'er', 'es', 'em', 'e'):
        if word.endswith(ending) and word[:-len(ending)] in WORDS:
            return WORDS[word[:-len(ending)]]
    if 'adjective' in pos:
        return 'ambiguous_adjective' if 'noun' in pos else 'adjective'
    return ''



def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0.0, '', 0)
    # Document, phrase-slot strength, determiner type, and slot age.
    _, slot, origin, age = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    kind = classify(word if word else token)
    context = slot
    if origin == 'an' and age == 0 and token.strip() in VOWEL_INITIAL_LETTERS:
        kind = 'letter_after_an'
    if kind == 'superlative' and (origin not in {'a', 'an'} or age != 0):
        context = 0.0
    if origin == 'foreign' and age == 0 and token and not token[0].isspace():
        context = slot = 0.0  # 'un-' may be a prefix rather than an article.
    if origin == 'demonstrative':
        context *= 0.8 if kind in {'reference', 'temporal_reference'} else 0.18
    elif origin == 'indefinite':
        specifying = kind in {'specified', 'reference', 'comparative'}
        context *= 1.1 if specifying else 0.25
    value = context * COEFFICIENTS.get(kind, 0.0)

    age += 1
    if word in {'a', 'an'}:
        slot, origin, age = 1.08, word, 0
    elif word in FOREIGN_ARTICLES and origin not in {'a', 'an'}:
        slot, origin, age = 1.55, 'foreign', 0
    elif word in INDEFINITE:
        slot, origin, age = 1.0, 'indefinite', 0
    elif word in {'this', 'that'}:
        slot, origin, age = 1.0, 'demonstrative', 0
    elif word in DEGREE or (
        word.endswith('ly') and 'adverb' in wordnet.parts_of_speech(word)
    ):
        slot *= 1.35
    elif not word or not any(ch.isalnum() for ch in word):
        slot *= 0.9
    else:
        slot *= 0.2 if kind else 0.0
    if age > 4:
        slot = 0.0
    return (doc, slot, origin, age), float(value)

"""Estimate a negative, equation-and-inference-heavy prose signal.

Counts over the last 128 tokens (and the most recent 32) estimate an
equation-and-inference-heavy writing context. Punctuation and grammatical
scaffolding respond most strongly;
word fragments, digits and mathematical symbols respond much less.
Counts reset at document boundaries. Numbers are fitted training coefficients.
This captures broad writing context, not all token-specific variation.
"""
import math
from collections import Counter, deque

READS = ()
REASON = set((
    'so thus therefore hence then alternatively wait hmm suppose '
    'perhaps maybe okay let').split())
UNCERTAIN = set((
    'possible impossible must need needs means implies would could should '
    'since because').split())
FIRST = set('i we me us my our'.split())

# Token classes: (baseline, response to the context level).
WORD_CLASSES = (
    (REASON, (-0.022, -0.893)),  # reasoning connectives
    (UNCERTAIN, (0.052, -0.789)),  # uncertainty and inference
    (set('the'.split()), (0.018, -1.175)),  # definite article
    (set('a an'.split()), (0.031, -0.313)),  # indefinite articles
    (set('am are be been being is'.split()), (-0.017, -0.807)),  # copulas
    (set('was were'.split()), (0.053, -0.497)),  # past copulas
    (set('can may might shall will'.split()), (-0.012, -0.947)),  # modal verbs
    (set('did do does had has have'.split()), (-0.007, -0.761)),  # auxiliaries
    (set('that these this those'.split()), (0.016, -0.992)),  # demonstratives
    (FIRST, (0.028, -0.630)),  # first person
    (set('it its'.split()), (0.033, -1.080)),  # impersonal pronoun
    (set('he her him his she their them they'.split()), (0.060, -0.801)),  # other third person
    (set('you your yours'.split()), (0.089, -0.764)),  # second person
    (set('although and but if or though unless while'.split()), (0.046, -0.961)),  # conjunctions
    (set('never no nor not'.split()), (0.023, -0.843)),  # negation
    (set(
        'about as at between by for from in into of on over through to under with'.split()),
     (0.056, -0.533)),  # prepositions
    (set('how what when where which who why'.split()), (0.011, -0.848)),  # relative words
    (set(
        'all another any both each either every neither only other same some such'.split()),
     (0.040, -0.613)),  # quantifiers
)

def response(s):
    w=s.strip(); low=w.lower()
    if s.startswith('<|') or s in ('<think>', '</think>'):
        return (-0.040, -0.120)
    if not w:
        if s.count('\n') >= 2: return (0.012, -1.121)
        if '\n' in s: return (0.012, -0.775)
        return (0.029, -0.258)
    if '\n' in s:
        sentence_end = any(c in w for c in '.?!')
        if s.count('\n') >= 2:
            if sentence_end: return (-0.089, -1.310)
            if ':' in w: return (-0.172, -0.973)
            return (0.072, -1.284)
        if sentence_end: return (0.065, -0.814)
        return (0.057, -0.315)
    if any(c in '.?!' for c in w) and not any(c.isalnum() for c in w):
        return (0.067, -1.115)
    if w==',': return (0.043, -1.015)
    if w==':': return (0.020, -0.781)
    if w==';': return (0.063, -0.385)
    if all(c in ')]}' for c in w): return (0.048, -0.266)
    if all(c in '([{' for c in w): return (-0.000, -0.210)
    if all(c in '=+-*/^<>≤≥≠≈×÷√∑∫' for c in w):
        return (0.026, -0.042)
    if w.isdigit(): return (0.031, -0.111)
    if not w.isascii(): return (0.003, -0.173)
    if w.startswith("'"): return (0.060, -0.869)
    for words, pair in WORD_CLASSES:
        if low in words: return pair
    if w.isalpha():
        if not s.startswith(' '): return (0.020, -0.131)
        return (0.012, -0.153) if w[0].isupper() else (0.021, -0.317)
    return (0.021, -0.144)


# Influence of log(1 + count) on the context score.
LONG_WEIGHTS = {
    'discourse': 1.052,
    'inference': 0.577,
    'first_person': 0.039,
    'paragraph': 0.433,
    'math_sign': 0.657,
    'digit': 0.124,
    'code': -0.031,
    'single_newline': -0.526,
}
RECENT_WEIGHTS = {
    'discourse': 0.760,
    'inference': 0.467,
    'first_person': 0.037,
    'paragraph': -0.062,
    'math_sign': 0.064,
}
CONTEXT_OFFSET = -2.361
ENGLISH_FRACTION_WEIGHT = -1.487
THINKING_WEIGHT = 0.744

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, deque(), Counter(), Counter(), 0)
    _, history, long, recent, thinking = carry
    s = prefix.token_strings[-1]
    word = s.strip().lower()
    flags = {
        'discourse': word in REASON,
        'inference': word in UNCERTAIN,
        'first_person': word in FIRST,
        'paragraph': '\n\n' in s,
        'math_sign': any(c in s for c in '=+^≤≥≠≈×÷√∑∫'),
        'digit': word.isdigit(),
        'code': any(c in s for c in '{};_'),
        'single_newline': '\n' in s and '\n\n' not in s,
        'english': s.startswith(' ') and word.isascii() and word.isalpha(),
    }
    cues = tuple(name for name, present in flags.items() if present)
    if len(history) >= 32:
        recent.subtract(history[-32])
    if len(history) >= 128:
        long.subtract(history.popleft())
    history.append(cues)
    recent.update(cues)
    long.update(cues)
    if s == '<think>': thinking = 1
    if s == '</think>': thinking = 0

    score = CONTEXT_OFFSET
    score += sum(w*math.log1p(long[k]) for k, w in LONG_WEIGHTS.items())
    score += sum(w*math.log1p(recent[k]) for k, w in RECENT_WEIGHTS.items())
    score += ENGLISH_FRACTION_WEIGHT * long['english']/128
    score += THINKING_WEIGHT * thinking
    context = 1/(1 + math.exp(-max(-25, min(25, score))))
    base, change = response(s)
    carry = (doc, history, long, recent, thinking)
    return carry, float(base + change*context)

"""Document-onset and isolated-space responses.

The onset pulse depends on token length, character class, English frequency,
and whether it looks like a code declaration, comment, or question word.
An identical-token run at the start is treated as continued onset.
The colon completing a document-initial "Title:" header gets a large pulse.
Elsewhere only a bare ASCII space gets a substantial prediction.
Its pulse is strongest after indentation, weaker after digits and in locally
double-spaced or escaped-newline text.  All tests use only past text.
"""
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
CODE_WORDS = set('''package import from class def function const var let
public private protected export include using namespace return'''.split())
QUESTION_WORDS = set('how what why when where which who whom whose whether'.split())


@lru_cache(maxsize=16384)
def onset(s):
    w = s.strip()
    n = len(w)
    letter = w.isalpha()
    latin = letter and all('LATIN' in unicodedata.name(c, '') for c in w)
    frequency = (round(2 * zipf_frequency(w.lower(), 'en')) / 2
                 if latin else 0)
    comment = w.startswith(('#', '//', '/*', '"""', "'''"))
    if n <= 1:
        if w.isascii() and w.isdigit():
            return 8.46
        if comment:
            return 12.12
        if s.startswith(' '):
            return 3.82
        if frequency >= 5:
            return 6.57
        if not letter:
            return 5.88
