"""Approximate a punctuation/discourse feature.

Parenthetical transitions are positive, especially when introduced by a comma.
Multiword phrases are recognized from their words, not from token IDs. Most
other tokens are near zero. Periods turn negative in runs of lowercased
sentences; the effect grows with the number of such sentence boundaries.
"""
import re

READS = ()
PARENTHETICAL_WORDS = {
    'however', 'moreover', 'meanwhile', 'nevertheless', 'nonetheless',
    'furthermore', 'respectively', 'although', 'though', 'according',
    'depending', 'right', 'too', 'course', 'example', 'instance', 'fact',
    'hand', 'way', 'all', 'contrast', 'turn', 'know', 'think',
}


def _predict(history, token):
    word = token.strip()
    lower = word.lower()
    recent = history[-64:]
    dot_distance = len(history.rsplit('.', 1)[-1]) if '.' in history else 1000
    comma_distance = len(history.rsplit(',', 1)[-1]) if ',' in history else 1000
    comma = history.rstrip().endswith(',')
    comma_count = recent.count(',')
    previous = re.findall(r'[A-Za-z]+', history[-40:])
    previous = previous[-1].lower() if previous else ''
    value = 0.0

    if lower == 'however':
        value = 2.9 if comma else 0.3
        if comma and dot_distance > 60:
            value *= 0.78
    elif lower == 'meanwhile':
        value = 4.5 if comma else 0.35
    elif lower == 'moreover':
        value = 2.6 if comma else -0.15
    elif lower in {'nevertheless', 'nonetheless', 'furthermore'}:
        value = 1.2 if comma else 0.0
    elif lower == 'respectively':
        value = 2.7 if comma else 0.07
    elif lower in {'although', 'though'}:
        value = (1.65 if lower == 'though' else 0.6) if comma else 0.05
    elif lower in {'according', 'depending'}:
        value = 1.15 if comma else 0.05
    elif lower in {'right', 'too'}:
        value = 2.0 if comma else 0.02
        if comma_count > 2:
            value *= 0.6
    elif lower == 'course':
        if previous == 'of':
            value = 2.7 if comma_distance <= 4 else 0.7
        else:
            value = -0.12
    elif lower in {'example', 'instance'}:
        if previous == 'for':
            value = 1.3 if comma_distance <= 5 else 0.08
        else:
            value = -0.05
    elif lower == 'fact':
        value = -0.12
        if previous == 'in':
            value = 2.1 if comma_distance <= 5 else 0.75
    elif lower == 'hand' and previous == 'other':
        value = 2.9 if comma_distance <= 15 else 0.8
    elif lower == 'way' and history.lower().rstrip().endswith('by the'):
        value = 2.2 if comma_distance <= 8 else 1.3
    elif lower == 'all':
        value = 1.7 if previous == 'after' else 0.05
    elif lower == 'contrast' and previous == 'in':
        value = 1.0 if comma_distance <= 5 else 0.35
    elif lower == 'turn' and previous == 'in':
        value = 0.9 if comma_distance <= 10 else 0.4
    elif lower == 'know' and previous == 'you':
        value = 1.1 if comma_distance <= 5 else 0.2
    elif lower == 'think' and previous == 'i':
        value = 0.45 if comma_distance <= 4 else 0.04
    if word and word[0].isupper():
        if lower == 'however':
            value = 0.2
        elif lower == 'meanwhile':
            value = 0.6
        elif lower == 'right':
            value = 0.15
        elif lower == 'moreover':
            value = -0.15
        else:
            value = 0.0
    return value


def _period(history):
    """Periods in all-lowercase sentence runs, versus ordinary full stops."""
    recent = history[-256:]
    letters = [c for c in recent if c.isalpha()]
    lowercase_text = bool(letters) and all(c.islower() for c in letters)
    dots = history.count('.')
    lower_starts = len(re.findall(r'\.\s*[a-z]', history))
    if lowercase_text and dots and lower_starts >= 0.96 * dots:
        if lower_starts <= 7:
            return -0.45
        since_comma = len(history.rsplit(',', 1)[-1]) if ',' in history else 1000
        if since_comma < 96:
            return -0.57
        return -1.0 if recent.count('.') <= 3 else -1.6
    if history[-64:].count(',') >= 4:
        return -0.12
    return -0.08 if lowercase_text else -0.01


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = _predict(history, token) if word in PARENTHETICAL_WORDS else 0.0
    if word == '.' and '\n' not in token:
        value = _period(history)
    return (doc, (history + token)[-2048:]), float(value)

"""Mostly a detector for source-file import declarations, not prose 'import'.

Completed package/import lines identify Java-style source; Python and quoted
JavaScript imports do not. File-initial declarations have separate responses.
Smaller rules cover namespace imports, indented stack frames, and dot leaders.
State is the current line and a few source-style flags, reset per document.
"""
import re

READS = ()
LINE_NUMBER = re.compile(r'^\s*\d+\t')
FILE_OPENERS = {
    'def': 1.99,
    'class': 1.93,
    'function': 0.82,
    'from': 0.56,
    'package': 0.36,
    'import': -0.49,
    'using': 0.06,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    if first:
        line, java, go = '', 0, False
        initial_package, imports, namespace = s == 'package', 0, False
    else:
        _, line, java, go, initial_package, imports, namespace = carry
    # A tab attached to the keyword can finish a displayed line number.
    indentation = s[:len(s) - len(s.lstrip())]
    margin = LINE_NUMBER.sub('', line + indentation)
    at_margin = not margin.strip()
    value = 0.0
    if s and set(s) == {'·'} and len(s) >= 2:
        value = 0.535
    elif s == '<|endoftext|>':
        value = -0.91 if first else -0.023
    elif s == '<|im_end|>':
        value = -0.036
    elif first and s in FILE_OPENERS:
        value = FILE_OPENERS[s]
    elif first and s.startswith('/*') and '\n' in s:
        value = -0.82
    elif first and s.startswith('//'):
        value = -0.90 if '\n' in s else -0.31
    elif s in ('import', '\timport') and at_margin:
        if s.startswith('\t'):
            value = 0.58 if java else -0.04
        elif java == 2:
            if initial_package:
                value = 1.75 if imports == 0 else 1.49
            else:
                value = 1.43
        elif java == 1:
            value = 1.0
        elif go:
            value = 1.05
        else:
            value = -0.05
    elif s == ' import':
        value = 0.08 if not at_margin else -0.05
    elif s == 'using' and at_margin:
        value = 0.60 if namespace else -0.03
    elif s == 'use' and at_margin:
        value = 0.65 if namespace else 0.0
    elif s in (' at', '\tat') and at_margin and not first:
        value = 0.58 if s.startswith('\t') else 0.16

    # Treat escaped newlines as line breaks too, for displayed source code.
    displayed = s.replace('\\r\\n', '\n').replace('\\n', '\n')
    parts = (line + displayed).split('\n')
    for completed in parts[:-1]:
        code = LINE_NUMBER.sub('', completed).strip()
        if code.startswith('package '):
            java = 2 if ';' in code else 0
            go, imports = ';' not in code, 0
        elif code.startswith('import ') and code.endswith(';'):
            if not any(c in code for c in "\"'`{"):
                java = max(java, 1)
                imports += 1
        namespace_line = code.startswith(('using ', 'namespace ', 'use '))
        if namespace_line and code.endswith(';'):
            namespace = True
    line = parts[-1][-512:]
    return (doc, line, java, go, initial_package, imports, namespace), value

