"""Component layers.1.mlp.down_proj:2581 (v1): document-boundary and abbreviation-period detector.

Main signal: the <|endoftext|> token that separates documents gives a strong positive
activation (about 1.0). The first token after a boundary is mildly negative. A period
that closes an abbreviation (e.g. "Cic.", "Ind.", "St.", "etc.") is mildly positive,
while the period in a speaker title ("Mr.", "Dr.") is negative. Everything else is ~0.
"""

READS = ()

END = "<|endoftext|>"
TITLES = {"Mr", "Mrs", "Ms", "Dr"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if tok == END:
        value = 0.96
    elif prev == END:
        value = -0.23
    elif tok == ".":
        word = prev.strip()
        if word in TITLES:
            value = -0.2
        elif word.isalpha() and len(word) <= 3:
            value = 0.3
        else:
            value = 0.0
    else:
        value = 0.0
    return carry, float(value)

