"""A sparse, spelling-sensitive ean/mean response.

Negative responses follow mean, clean, bean/Jean/Dean/lean, and split
 e + an spellings. Chinese average/even (均/匀) and clean (净) words also
respond. Verbal mean and many inflections are weaker. A few positive
nasal-spelling and punctuation responses are included. Only the previous
token is remembered; these rules omit longer-context and token-specific
variation in the activation's magnitude.
"""
import re
import regex
from anyascii import anyascii

READS = ()
EAN_ROOTS = {
    'bean': -4.18, 'jean': -2.97, 'dean': -3.09,
    'lean': -2.94, 'sean': -1.85,
}
VERB_PREDECESSORS = {
    'i', 'you', 'we', 'they', 'does', 'do', 'did', 'will', 'would',
    'could', 'might', 'can', 'may', 'to', 'not', 'that', 'this', 'it',
    'what', 'really', 'actually',
}


def response(token, previous):
    word = token.strip()
    lower = word.lower().lstrip('._(')
    if word == ':' and previous.strip() == 'Title':
        return -3.0
    if word == '··':
        return 1.1
    if word.endswith(('净', '淨')):
        return -1.6
    if word == '均':
        return -7.0
    if word.endswith('均'):
        return -8.2 if word == '人均' else -5.87
    if word.startswith('均') and len(word) == 2:
        return -1.2
    if word in ('匀', '勻', '钧', '鈞'):
        return -4.0
    if lower == 'ean':
        return -5.0
    match = re.fullmatch(
        r'(bean|jean|dean|lean|mean|clean|sean)(s|ed|ing|er|ers|ly)?', lower)
    if match:
        root, ending = match.groups()
        if root == 'mean':
            if ending:
                return -0.09
            if not token[:1].isspace():
                return -2.7
            if word[0].isupper():
                return -1.81
            before = previous.strip().lower()
            if before in VERB_PREDECESSORS:
                return -0.24
            if before in {'a', 'the', 'arithmetic', 'geometric', 'harmonic'}:
                return -1.8
            return -1.3
        if root == 'clean':
            if word.isupper():
                return -3.0
            if ending:
                return -0.5
            return -1.11 if token[:1].isspace() else -2.16
        return EAN_ROOTS[root]
    if lower in ('demean', 'demeaning'):
        return -2.7
    if lower in ('peanut', 'peanuts'):
        return -0.6
    if (token[:1].isspace() or not previous or
            not regex.fullmatch(r'[\p{Latin}\p{Cyrillic}]+', word) or
            not regex.search(r'[\p{Latin}\p{Cyrillic}]$', previous)):
        return -0.001
    # Do not join words at a camelCase boundary. Transliteration also
    # permits accented vowels and Cyrillic е + ан, without joining Han words.
    if previous[-1:].islower() and word[:1].isupper():
        return -0.001
    fragment = anyascii(word).lower()
    before = anyascii(previous).lower()
    last = before[-1:] if before else ''
    if re.fullmatch(r'a[nm][a-z]*', fragment):
        if last == 'e':
            if fragment.startswith(('anc', 'ant', 'ang', 'answ')):
                return -0.001
            if fragment.startswith('am'):
                return -0.8
            if fragment.startswith('and'):
                return -3.0 if len(before.strip()) < 7 else -0.001
            return -5.8
        if last == 'o' and fragment.startswith('an'):
            return -2.5
        if word == 'ан':
            return -0.2 if last in 'aiuy' else 0.7
        if last in 'rmv' and last and fragment in ('an', 'ans', 'ann'):
            return 0.5
    if re.fullmatch(r'[mp]an', lower) and previous.lower().endswith('m'):
        return 2.0
    return -0.001


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    token = prefix.token_strings[-1]
    return (document, token), response(token, previous)

