            value = 0.008
    elif word == '#####':
        value = 0.07
        if tail.endswith(('...\n', '...\r\n')):
            value = 0.44
        elif tail.endswith((' answer', ' answers')):
            value = 0.51
    elif position > 0:
        value = {'-': 0.043, ' -': 0.018, '_': -0.05,
                 '{': 0.035, ' &': 0.03, '%': 0.025,
                 '+': 0.015}.get(token, value)

    leading_escapes = leading_escapes and token in ('\\t', '\\n')
    tail = (tail + token)[-100:]
    return (doc, token, tail, leading_escapes, position + 1), value

"""A partial token-and-quantity-language approximation.

Most tokens get a near-zero score. Small word-class offsets distinguish
quantification and limiting language. Larger rules recognize alternatives,
unit conversions, relative times, Chinese bounds, and two code conventions.
Dot-leader runs and document-initial token shapes have separate offsets. These rules
capture only a small part of the component's lexical variation.
"""
import unicodedata
import regex
import inflect

READS = ()
_engine = inflect.engine()
NUMBERS = {_engine.number_to_words(n) for n in range(21)}
NUMBERS |= {_engine.number_to_words(n) for n in range(30, 100, 10)}
NUMBERS |= {'hundred', 'thousand', 'million', 'billion', 'trillion'}
AMOUNTS = NUMBERS | set(
    'many much several some any each all every few little more less most '
    'enough number range variety multitude couple pair lot plenty multiple '
    'numerous'.split()
)

def plural_forms(words):
    words = set(words.split())
    return words | {_engine.plural(w) for w in words}

TIME = plural_forms('second minute hour day week month year century')
MEASURES = plural_forms('mile kilometre kilometer metre meter foot inch acre yard')
MEASURES |= {'cm', 'mm', 'km', 'm'}
BE = set('am is are was were be been being'.split())
# Limitation, alternatives, distribution, approximation and correspondence.
WORD_CLASSES = (
    (-0.019, 'if unless whether'),
    (-0.022, 'for'),
    (-0.050, 'about'),
    (-0.041, 'only just exactly'),
    (-0.053, 'most least'),
    (-0.044, 'because therefore however hence consequently'),
    (-0.035, 'both either'),
    (-0.065, 'few several'),
    (0.067, 'each'),
    (-0.014, 'per'),
    (0.036, 'some'),
    (0.033, 'around approximately roughly nearly almost'),
    (0.108, 'respectively'),
)
WORD_CLASSES = tuple((v, set(words.split())) for v, words in WORD_CLASSES)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        age, history = 0, ()
    else:
        _, age, history = carry
    text = prefix.token_strings[-1]
    s = text.strip()
    w = s.lower()
    p = history[-1].strip().lower() if history else ''
    recent = []
    for t in reversed(history[-7:]):
        q = t.strip().lower()
        if any(c in t for c in '.;!?\n') and not q.replace('.', '').isdigit():
            break
        recent.append(q)
    near_amount = any(t in AMOUNTS or t.isnumeric() for t in recent[:3])
    recent_amount = any(t in AMOUNTS or t.isnumeric() for t in recent)

    value = 0.003 - 0.004 * text.startswith(' ')
    for offset, words in WORD_CLASSES:
        if w in words:
            value += offset
    if s.isnumeric():
        value += 0.002 - 0.005 * (s in '13579' and len(s) == 1)
        value += 0.004 * recent_amount
        value -= 0.006 * (p.isnumeric() or p in NUMBERS)
    if p in AMOUNTS or p.isnumeric():
        value -= 0.003
    if near_amount:
        value -= 0.002
        if w in NUMBERS:
            value += 0.066
        if w == 'about':
            value -= 0.083
    if p.isnumeric() and w in {'s', 'ms', 'm', 'c', 'am', 'pm'}:
        value -= 0.038
    if p in TIME and w in {'later', 'before', 'after', 'prior', 'ago'}:
        value -= 0.119
    if p == 'or' and w in AMOUNTS:
        value += 0.08
    if w == 'not' and p == 'if':
        value += 0.08
        if len(history) > 1 and history[-2].strip() in {',', '('}:
            value += 0.40
    if '(' in s and p in MEASURES:
        value += 0.15
    if '±' in s:
        value += 0.13
    if s == '及以上':  # "and above", an inclusive lower bound
        value += 0.65
    if s == '各' and p.endswith('各式'):  # "all kinds of"
        value += 0.60
    if s and set(s) == {'·'} and (
        len(s) >= 3 or (len(s) >= 2 and p and set(p) == {'·'})
    ):  # a run of middle-dot leaders, not an interpunct in a name
        value += 0.82
    if s == 'By' and any('/*' in t for t in history[-3:]):
        value += 0.55
    if age == 1 and s == '()' and p == '(function':
        value += 1.50

    if age == 0:
        if s.isnumeric():
            value -= 0.053
        if s.isascii() and s.isalpha():
            value -= 0.108
            value += 0.046 * s[0].isupper()
            value -= 0.059 * (len(s) <= 2)
        if not s:
            value -= 0.202
            value -= 0.138 * ('\n' in text)
        if s and all(unicodedata.category(c).startswith('P') for c in s):
            value -= 0.149
        if regex.search(r'\p{Script=Han}', s):
            value += 0.088
        if w in BE:
            value += 0.131
        if w == 'the':
            value -= 0.137
    return (doc, age + 1, (history + (text,))[-7:]), float(value)

programs.haiku:
"""Layer 1 MLP down-projection, component 2586: a weak, mostly token-driven signal.

What it does, in plain terms:

1. Start of a text (the first token after a document break, or after <|endoftext|>):
   the component writes a token-specific value. It is negative for word fragments
   (lowercase pieces, and words with a leading space that continue a sentence),
   positive for Chinese/Japanese/Korean characters, and near zero otherwise.
2. Inside a text it is small. It is negative on magnitude words (million, billion,
   percent, seconds, years, kB, MB, degrees C), most strongly right after a number,
   and mildly negative on a few quantity words (about, several, least, multiple).
   It is positive on "±", "each", "respectively" and some Chinese quantity words.
3. Everywhere else it is 0.

The predictions are class means fitted on training text, so the program is a small
set of word classes with signed strengths rather than a per-token table.
"""

import re

READS = ()

END = "<|endoftext|>"
CJK = re.compile(r"[぀-ヿ一-鿿가-힯]")
NUMBER = re.compile(r"\s*\d+")
MAGNITUDE = {
    "million", "billion", "trillion", "percent", "%", "kB", "MB", "GB", "seconds",
    "years", "miles", "kilometres", "calories", "°C", "°F", "млн", "рублей", "亿元",
}
FEW_NEGATIVE = {"about", "several", "least", "multiple"}
POSITIVE = {"±", "respectively", "each", "各", "各种", "多个", "有些"}


def _opens_text(prefix):
    """True where a new text starts: position 0, a document change, or after <|endoftext|>."""
    if len(prefix.token_ids) == 1:
        return True
    if prefix.document_ids[-1] != prefix.document_ids[-2]:
        return True
    return prefix.token_strings[-2] == END


def _start_value(s):
    """Activation at the start of a text, from the surface form of its first token."""
    if CJK.search(s):
        return 0.12
    if re.fullmatch(r"[a-z]+", s) or re.fullmatch(r"\W+", s):
        return -0.19
    if s.startswith(" "):
        return -0.12
    if s.isdigit():
        return -0.05
    return -0.03


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if _opens_text(prefix):
        return carry, _start_value(s)
    word = s.strip()
    after_number = len(prefix.token_strings) > 1 and bool(NUMBER.fullmatch(prefix.token_strings[-2]))
    if word in MAGNITUDE:
        return carry, -0.12 if after_number else -0.04
    if word in POSITIVE:
        return carry, 0.20 if after_number else 0.07
    if word in FEW_NEGATIVE:
        return carry, -0.07
    return carry, 0.0

programs.sol:
"""Approximate sparse responses to dialogue framing and stock text constructions.

Training examples showed large negative pulses at internal message starts,
think starts, tool-response endings, and certain punctuation-led constructions.
The rules below cover shell clauses, bracketed references/interface labels,
wiki navigation, and cross-reference/math phrases. Test RUN banners and
namespace declarations give positive pulses; other dialogue tags have small
signed responses. Unmatched text is zero, leaving finer lexical effects out.
Only the previous token and a bounded text suffix are needed.
"""
import re

READS = ()
TAGS = {
    '<|im_start|>': -1.14,
    '<|im_end|>': 0.08,
    '<think>': -1.77,
    '</think>': -0.22,
    '<tool_call>': 0.32,
    '</tool_call>': 0.10,
    '<tool_response>': -0.46,
    '</tool_response>': -1.33,
}


def response(s, previous, tail):
    if s in TAGS:
        if s == '<|im_start|>' and previous != '\n':
            return 0.046
        return TAGS[s]
    word, before = s.strip(), previous.rstrip()

    # Shell grammar: semicolon followed by a control keyword.
    if before.endswith(';'):
        if word == 'then':
            if before.replace(' ', '').endswith('];'):
                return -15.3
            if re.search(r'\b(?:if|elif)\b', tail):
                return -12.8
            return -2.0
        if word == 'do' and re.search(r'\b(?:for|while)\b', tail):
            return -15.5 if s.startswith(' ') else -9.2
        if word == 'done':
            return -2.0
        if s == ' ++':
            return -3.4
        if word in ('however', 'therefore', 'thus', 'otherwise', 'rather'):
            return -3.1

    # Prose cross references and wiki navigation/editing boilerplate.
    if s == ' see' and before.endswith((',', ';')):
        if ';' in before or re.search(r'\b[Ff]or\b', tail[-160:]):
            return -3.5
    if s == ' note' and previous in (' supra', ' infra'):
        return -8.0 if previous == ' supra' else -2.0
    if s == ' links' and previous.strip() == 'External':
        return -3.2
    if before.endswith('['):
        if word == 'edit':
            return -12.4
        if word == 'прав':  # Russian wiki 'edit' link, split across tokens.
            return -8.4
        if word == '編':  # Beginning of Japanese wiki's edit label.
            return -3.2
        if word == 'OPTIONS':  # Command-line usage placeholder.
            return -6.9
        if word in ('options', 'source'):  # Section/source-link labels.
            return -3.2
    if s == 'ить' and previous == 'прав':
        return -5.2
    if s == ' edit' and before.endswith('|') and '[edit' in tail:
        return -4.3

    # Numeric bracket references, including chained and keyed citations.
    if s.isascii() and s.isdigit() and s != '0' and before.endswith('['):
        if before.endswith('.['):
            return -4.7 if s == '1' else -3.8
        if before == '][':
            return -1.3 if s == '1' else -0.7
        if before.strip() == '[':
            return -0.38 if s == '1' else -0.16
        return -0.5
    if s == '][' and previous.isdigit():
        return -1.43
    if s == '[@':
        if before.endswith('^'):
            return -3.4
        return -2.8 if before.endswith('[') else -0.8

    if word == 'display':  # The beginning of LaTeX's displaystyle command.
        if tail.endswith('${\\'):
            return -12.7
        if tail.endswith('{\\'):
            return -4.9
        if previous == '\\':
            return -1.0
    if s == ' RUN' and before.endswith('==='):
        return 1.23
    if s == ' std' and previous == ' namespace':
        return 2.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail = '', ''
    else:
        _, previous, tail = carry
    s = prefix.token_strings[-1]
    value = response(s, previous, tail)
    return (doc, s, (tail + s)[-512:]), value

programs.haiku:
"""Markup and chat-template structure, as this layer-1 MLP unit reads it.

The unit is silent on almost all text. It goes negative on a few kinds of structural token:
  - chat-template turn openers: <|im_start|> right after a newline (the end of the previous turn),
    plus the tool-transcript and reasoning markers </tool_response>, <think>, <tool_response>;
  - wiki/markup link and citation syntax: "[" followed by "@" or "edit", a "][" between
    citation numbers, " links" after "External" (as in "External links");
  - a LaTeX "\\display" command (a backslash followed by "display").
It is mildly positive on " RUN" after "===" (Go test output). Everything else is about 0.
"""

READS = ()

MARKER_VALUE = {
    "<think>": -1.8,
    "</tool_response>": -1.3,
    "<tool_response>": -0.5,
}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    same_doc = len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    if cur == "<|im_start|>":
        return carry, -1.0 if prev.endswith("\n") else 0.0
    if cur in MARKER_VALUE:
        return carry, MARKER_VALUE[cur]
    if cur == "display" and prev.endswith("\\"):
        return carry, -7.0
    if cur == "edit" and prev == "[":
        return carry, -10.0
    if cur == "[@":
        return carry, -2.5
    if cur == "][" and prev.isdigit():
        return carry, -1.1
    if cur == " links" and prev == "External":
        return carry, -3.0
    if cur == " RUN" and prev == "===":
        return carry, 1.3
    return carry, 0.0

programs.sol:
"""Opening-token response, strongest for spaced mathematical/layout symbols.

The opening of each packed document (including the row's first token) is special.
An initial run of identical tokens retains that response. The rules approximate
its dependence on token shape: nonbreaking spaces, operators and variables are
positive; digits and unspaced words are mostly negative. Later tokens get zero.
Common mathematical functions and source-module declarations also have
opening-specific values. Small later lexical/context effects are omitted.
"""
import unicodedata

READS = ()
MATH_FUNCTIONS = {"sin", "cos", "tan", "log", "ln", "exp", "sqrt"}
MODULE_DECLARATIONS = {"using", "import", "export", "package", "from"}


def opening_value(text):
    s = text.strip()
    spaced = text.startswith(' ')
    if '\xa0' in text:
        return 7.0 if spaced else 4.8
    if not s:
        if text == '\t':
            return -1.25
        if '\n' in text or '\r' in text:
            return -0.24
        if len(text) == 1:
            return 0.2
        return 0.05
    if set(s) == {'^'}:
        return 2.6 if len(s) == 1 else 3.6
    if len(s) > 1 and set(s) == {'·'}:
        return 3.2
    if not any(c.isalnum() for c in s):
        if spaced:
            if s in {'+', '-'}:
                return 6.6
            if s == '>':
                return 7.4
            if s in {'&', '>>', '<<'}:
                return 4.0
            if s == '_':
                return 3.4
            if s in {'–', '—', '|', '||', '&&', '=>', '\\', '*', '/', '=', '%'}:
                return 2.0
        if s == '+':
            return 3.3
        if s == '−':
            return 3.8
        if s.startswith('(-') or s.startswith('*('):
            return 3.4
        if '_' in s or '^' in s:
            return 1.3
        return 0.4 if spaced else 0.07
    if s.isascii() and s.isdigit():
        if s == '0':
            return -1.44
        if s == '1':
            return -0.1
        return -0.49
    if s in MATH_FUNCTIONS:
        return 1.3
    if text in MODULE_DECLARATIONS:
        return -1.3
    if s.isascii() and len(s) == 1 and s.islower():
        if s in 'xyz':
            return 2.94 if spaced else 1.22
        if s == 'a' and spaced:
            return 0.58
        return 1.13 if spaced else -0.5
    if len(s) == 2 and s[0] == '(' and s[1].isascii() and s[1].islower():
        return 2.45
    if s.isascii() and s.isalpha():
        if s.istitle():
            return 0.1 if spaced else -0.38
        if s.isupper():
            return -0.18 if spaced else -0.56
        return -0.09 if spaced else -0.29
    if all('CJK' in unicodedata.name(c, '') for c in s):
        return -0.19
    return 0.32 if spaced else 0.05


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        first, uniform = text, True
    else:
        _, first, uniform = carry
        uniform = uniform and text == first
    value = opening_value(text) if uniform else 0.0
    return (doc, first, uniform), value

