"""Estimate early word-internal subword responses from spelling.

Track the unfinished alphabetic word, resetting at document boundaries.
Within its first five letters, respond to vowel-bearing continuations of
consonant clusters, consonants closing vowel-final fragments, and vowels
meeting across a token boundary. Corpus frequencies damp familiar words;
rare capitalized strings can respond strongly. Most other positions are
near zero, with a small first-position baseline. These are spelling rules,
not token-ID lookups, and only approximate the component.
"""
import re
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency
import regex

READS = ()
VOWELS = frozenset('aeiouy')

@lru_cache(maxsize=30000)
def frequency(word, language='en'):
    return zipf_frequency(word.lower(), language)


def vowel_shape(word):
    plain = unicodedata.normalize('NFD', word.lower())
    plain = ''.join(c for c in plain if not unicodedata.combining(c))
    return plain, sum(c in VOWELS for c in plain)


def response(left, token):
    word = left + token
    if len(word) > 5:
        return 0.067 if len(left) <= 2 else -0.008
    left_form, left_vowels = vowel_shape(left)
    token_form, token_vowels = vowel_shape(token)
    if frequency(left) <= 1.75:
        if left_form[-1] in VOWELS:
            return 0.34
        if regex.search(r'\p{Script=Cyrillic}', token):
            return 0.29 if len(word) <= 4 else 0.06
        return 0.036
    if left_form[-1] in VOWELS:
        if token_form[0] not in VOWELS:
            if len(left) >= 2 and token_vowels == 0:
                return 0.54 if left_vowels <= 1 else 0.25
            return 0.17
        if left_vowels > 1:
            return 0.19
        if token_vowels > 1:
            return 0.36
        foreign = max(frequency(word, lang)
                      for lang in ('de', 'fr', 'es', 'it', 'pl', 'pt'))
        if foreign > 1.75:
            return 0.69
        return 1.38 if left[0].isupper() else 0.74
