"""Explains layers.1.mlp.down_proj:2595, a sparse, mostly-quiet MLP output direction.

Most of the time it is near zero (std ~0.05). Its large values come from two places:

1. Document starts. The first token of a document has no earlier context, so its value is a
   fixed function of the token itself. Rough classes: a line-ending full stop ('.\\n') is
   strongly positive (~+1.5); lowercase word fragments, digits and non-ASCII letters are mildly
   positive (~+0.3); question words and common mid-sentence prepositions ('How', 'What', ' to',
   ' of', ...) are negative (~-0.5).
2. The metadata label 'Title:' opening a document. The ':' right after a document-initial
   'Title' fires strongly (~+7.9 in the data).

Smaller effects: the full-width colon '：' used as a field label in Chinese forms (~+0.2), and a few
Chinese demonstratives such as 这种 and 什么 (~-0.3). Everything else predicts 0.
"""
READS = ()

NEWLINE_ENDS = {".\n", ".\n\n", "。\n"}
QUESTION_OR_PREP = {"How", "What", "When", "In", "Question", " to", " of", " for", " that", " is", " in", " by"}
FULLWIDTH_COLONS = {"：", "：\n"}
DEMONSTRATIVE_CN = {"这种", "什么", "这个", "这一", "是什么", "这款"}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    n = len(prefix)
    docs = prefix.document_ids
    if n == 1 or docs[-1] != docs[-2]:  # first token of a document
        if s in NEWLINE_ENDS:
            return None, 1.5
        if s in QUESTION_OR_PREP:
            return None, -0.5
        if s.isdigit() and s != "0":
            return None, 0.3
        if s.isalpha() and (s.islower() or not s.isascii()):
            return None, 0.3
        return None, 0.0
    if s == ":" and prefix.token_strings[-2] == "Title" and (n == 2 or docs[-3] != docs[-2]):
        return None, 7.9  # 'Title:' opening a document
    if s in FULLWIDTH_COLONS:
        return None, 0.2
    if s in DEMONSTRATIVE_CN:
        return None, -0.3
    return None, 0.0

