"""A spelling-based approximation to a sparse g-fragment response.

Short gent-/gentle- spellings are strongly positive; several other short
g-initial families are weaker. Splits between g and the rest of a syllable
matter. Short continuations after a Cyrillic г are usually negative,
especially before е/и plus a stop. A small additional rule recognizes
com immediately after a package declaration. Other cases receive zero.

The constants are rounded averages of training spelling classes. This is
not a semantic kindness detector: names and word-internal fragments count.
"""
import re

READS = ()

# bare spelling, split immediately after g, longer spelling, later suffix
G_FAMILIES = {
    'gem':    (2.3, 2.2, 0.1, 0.0),
    'gil':    (1.1, 1.3, 0.3, 0.3),
    'gift':   (1.8, 3.7, 0.6, 1.7),
    'gel':    (1.0, 0.7, 0.2, 0.0),
    'groom':  (3.7, 4.7, 0.0, 0.0),
    'ginger': (2.0, 2.4, 0.0, 2.0),
}


def response(previous_word, previous_token, token):
    s = token.lower()
    continuing = bool(s) and s[0].isalpha()
    text = previous_word + s if continuing else s
    match = re.search(r'[^\W\d_]+$', text)
    word = match.group() if match else ''
    boundary = len(previous_word) if continuing and s.isalpha() else 0
    if not word:
        return word, 0.0

    # Cyrillic g: distinguish short vowel-and-consonant continuations.
    if previous_token.strip().lower() == 'г' and continuing:
        if s[0] in 'еиі':
            if len(s) > 1 and s[1] in 'дпк':
                return word, -9.0
            if len(s) <= 3:
                if s[1:2] in ('м', 'л', 'р', 'з'):
                    return word, -4.8
                return word, -3.8 if len(s) == 1 else -1.6
        if len(s) <= 3 and s[0] in 'аоуыэюяё':
            if s.startswith(('ом', 'ум')):
                return word, -6.0
            if s[0] == 'а' and s[1:2] in ('', 'б', 'м', 'л', 'р'):
                return word, -3.8
            return word, -1.2
        return word, -0.3

    # A Latin stem must start the word or have begun in an earlier token.
    for root in ('gent', *G_FAMILIES):
        i = word.rfind(root)
        if i < 0 or (i != 0 and i >= boundary):
            continue
        part = word[i:]
        if root == 'gent' and len(part) <= 10:
            if boundary == i + 1:
                length = len(previous_token.strip())
                if length <= 1:
                    return word, 6.5
                return word, 3.0 if length <= 4 else 1.2
            if boundary == i + 4 and i == 0 and token[:1].islower():
