                    return word, 7.5
            if boundary > i + 4 and part in ('gentleman', 'gentlemen'):
                return word, 4.0
            if boundary == i + 4 and s in ('e', 'es', 'i'):
                return word, 3.8
            if boundary > i:
                return word, 0.3
            if part == 'gente':
                return word, 2.8
            if part.startswith(('gentle', 'gently')) or part in ('gent', 'gents'):
                return word, 7.0
        if root != 'gent' and len(part) <= len(root) + 2:
            bare, split, longer, suffix = G_FAMILIES[root]
            if boundary == i + 1:
                return word, split
            if len(part) == len(root):
                return word, bare
            if boundary >= i + len(root):
