        if s.startswith(('ip', 'id', 'iz')):
            return word, -0.9
        if s.startswith('en') and 2 < len(s) <= 4:
            return word, 1.0
    if previous_token.strip() == 'package' and s.strip() == 'com':
        return word, 2.8
    return word, 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous_word, previous_token = '', ''
    else:
        _, previous_word, previous_token = carry
    token = prefix.token_strings[-1]
    word, value = response(previous_word, previous_token, token)
    return (doc, word[-40:], token), value

