    if before.endswith('每') and re.fullmatch(r'一[个年天次]', c):
        return 1.8
    if c in {'事情', '的事情'}:
        return 2.0 if before.endswith('好') else .55
    if c == '时候' and before.endswith('的'):
        return 1.5
    if c == '会' and before.endswith('将'):
        return 1.5
    if c == '是' and before.endswith(('却', '自', '如')):
