    if token == 'おります':
        return 1.2
    if token.startswith('いただ') and previous.endswith('せて'):
        return 1.6
    if token.endswith('できます'):
        return 1.5 if previous.endswith('が') else .48
    if token == 'でしょうか':
        return .95
    if token == 'には' and previous == 'ため':
        return 1.0
    if token in {'れば', 'えば', 'ても'}:
        return .45
    if token == 'も' and previous.endswith('けれど'):
        return 1.4
    if token == 'して' and previous.endswith('どう'):
        return 1.1
