WHAT_NEXT = {'a': 2.59, 'an': 4.5, 'about': 1.76, 'happens': -1.20}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, older, word = '', '', ''
    else:
        _, previous, older, word = carry
    token = prefix.token_strings[-1]
    current, prior = token.strip(), previous.strip()
    spelling = anyascii(current).lower()
    tail = anyascii(word).lower()
    continuation = bool(token and token[0].isalpha())
    value = -0.003

    if prior.lower() == 'at' and current in AT_NEXT:
        value = AT_NEXT[current]
        if prior == 'At' and current == 'the':
            value = -2.45
        if older.strip().lower().startswith('look'):
            if current == 'the':
                value = -0.34
            elif current == 'all':
                value = 2.69
    elif prior.lower() == 'what' and current in WHAT_NEXT:
        value = WHAT_NEXT[current]
        if prior == 'What' and current == 'a':
            value = 4.51

