    if spelling.startswith('atmospheric'):
        value = -4.82
    elif spelling.startswith('atmosphere'):
        value = -2.35
    elif spelling.startswith('atm'):
        value = -6.27
    elif spelling.startswith('atomic'):
        value = -2.26 if continuation else -0.53
    elif spelling.startswith('atom'):
