import unicodedata
from atoms import FULLWIDTH_DIGITS

READS = ()
QUOTES = frozenset('‘’“”„‟‚‛')


def quote_amplitude(text, mark, single_open, german_open):
    if mark == '’':
        after = text.split(mark, 1)[1]
        if single_open and not after[:1].isalpha():
            return -1.0  # A closing single quotation mark, not an apostrophe.
        return -6.15 if after.lower() == 's' else -5.8
    if mark == '‘':
        return -3.2
    if mark == '“':
        if german_open:
            return -1.5  # German-style quotes open with „ and close with “.
        return -5.3 if text.lstrip().startswith(mark) else -4.25
    if mark == '”':
        return -2.1 if text.strip() == mark else -1.7
    return -0.45


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, False, False, '')
    _, quote_count, single_open, german_open, recent = carry
    text = prefix.token_strings[-1]
    mark = next((ch for ch in text if ch in QUOTES), '')
    value = 0.0
    if mark:
        value = quote_amplitude(text, mark, single_open, german_open)
        if mark == '“' and not german_open:
            han = len(regex.findall(r'\p{Script=Han}', recent))
            value += 3.72 * han / max(len(recent), 1)
        value /= (1.0 + quote_count) ** 0.5
    elif '\t' in text:
        # A tab merged with space padding does not behave like bare tabs.
        value = 0.0 if text.isspace() and ' ' in text else (
            -0.56 if text.isspace() else -0.4
        )
        if text == '\t' and recent.endswith('\t'):
            value = -0.12
    elif '\xa0' in text:
        value = -0.25
    elif '–' in text:
        value = -0.5
    elif '—' in text:
        value = -0.1 if text.startswith(' ') else -0.35
    elif '…' in text:
        value = -0.5
    elif any('LATIN' in unicodedata.name(c, '') and
             'LIGATURE' in unicodedata.name(c, '') and
             unicodedata.decomposition(c).startswith('<compat>')
