    elif '«' in text:
        value = -0.3
    for ch in text:
        if ch in QUOTES:
            quote_count += 1
        elif ch == "'":
            quote_count += 0.2
        if ch == '‘':
            single_open = True
        elif ch == '’' and not text.split('’', 1)[1][:1].isalpha():
            single_open = False
        elif ch == '„':
            german_open = True
        elif ch == '“':
            german_open = False
    carry = (doc, quote_count, single_open, german_open, (recent + text)[-80:])
    return carry, float(value)

"""Approximate an apostrophe/contraction-boundary signal.

Large values mark missing, escaped, spaced or misdecoded apostrophes and
contraction endings. These are spelling cues, not a grammaticality test:
