READS = ()
CONTRACTION_BASES = set('i you he she it we they who what that there here'.split())
NEGATED_BASES = set(('don doesn didn isn aren wasn weren haven hasn hadn '
                'wouldn shouldn couldn mustn needn won can ain').split())
