    'm': {'i'}, 're': {'you', 'we', 'they', 'there'},
    've': {'i', 'you', 'we', 'they', 'who', 'could', 'would', 'should', 'might'},
    'll': CONTRACTION_BASES, 'd': CONTRACTION_BASES,
    's': {'he', 'she', 'it', 'that', 'there', 'here', 'who', 'what', 'how', 'let'},
    't': NEGATED_BASES,
