               'would should could must').split()),
}
# Response levels for bare endings and for whole apostrophe-less spellings.
MISSING = {'m': 3.0, 're': 4.8, 've': 9.2, 'll': 3.5, 't': 5.6, 'nt': 4.0}
WHOLE = {'s': 2.5, 't': 1.0, 're': 8.2}
