        return -0.67
    if token == '<|endoftext|>' and not before:
        return 4.2
    if token == '\r' and not before.strip('\r'):
        return 4.0
    if len(token) >= 2 and not token.strip('·'):
        return 2.1
    if token in {' pas', ' inte'}:  # French and Swedish negation.
        return 1.1
    if (token in MARKS or token == '`') and word:
        if token == '`' and code:
            return 0.0
        if stem in NEGATED_BASES:
            return 8.4
        if stem in CONTRACTION_BASES:
            return 5.9
        return MARKS.get(token, 0.0) if noun_or_name(word) else 0.0
    if ending in STEMS:
        if code:
            return -0.07
        if re.search(r'(?:\\x99|\\u2019|&#(?:39|x27);?)$', before):
            return 5.9
        if before.endswith(('â\x80\x99', 'â€™')):
            return 3.8
        if before.endswith('`'):
            return 4.7
        if before.endswith("\\'"):
            return 3.8
        if ending in {'s', 'd', 'm'} and token.strip().isupper():
            return -0.07
        quote = re.search(r"([^\W\d_]+)\s*(['‘’])$", before)
