        return 0.03
    if lower in {"'d", '’d'}:
        return 1.3 if stem == 'i' and lower[0] == "'" else 0.3
    # Word recognition spans token boundaries, e.g. th + ats.
    whole = re.search(r'(?<!\w)([^\W\d_]+)$', before + token)
    if len(ending) > 1 and whole:
        spelling = whole[1].lower()
        for suffix, value in WHOLE.items():
            base = spelling[:-len(suffix)]
            if spelling.endswith(suffix) and base in STEMS[suffix]:
                contracted = zipf_frequency(base + "'" + suffix, 'en')
                if contracted > zipf_frequency(spelling, 'en') + .7:
                    return value
    if token == " '" and (stem in CONTRACTION_BASES or stem in NEGATED_BASES or stem == 'let') and (
        stem != 'i' or word == 'I'):
        return 1.8
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, (before + token)[-100:]), score(token, before)

"""An initial-token pulse, sustained by identical leading repetitions.

Its height is estimated from token shape and grammatical class.  After the
first different token it is zero.  These category averages deliberately omit
word-specific variation and the small activations in ordinary running text.
