READS = ()

FUNCTION_WORDS = set('''
of to in for on with at from by as into about over after under between through
without before during and or but if so than while because although when unless
since be is are was were been being am have has had do does did can could may
might shall should will would must
'''.split())


def initial_height(token):
    word = token.strip()
    if not word:
        if token == ' ':
            return -1.8
        if '\r' in token and '\n' not in token:
            return 17.6
        return 2.3 if '\n' in token else 2.8
    if token.startswith('<|'):
        return 9.4
    if word == '0':
        return -2.1
    if word.isdigit():
        return 8.5
    if word.lower() in {'a', 'an', 'the'}:
        return 10.1
    if len(word) == 1 and word.isalpha():
        if word.isupper():
            return 11.9
        if word.islower():
            return 7.2
    if word.isupper():
        return 8.4
    if word.lower() in FUNCTION_WORDS:
        return 3.2
    if word[0].isalpha():
        return 6.2 if word.isascii() else 5.4
    if word.startswith('#'):
        return 7.4
    if word.startswith(('//', '/*')):
        return 8.0
    if word.startswith('_'):
        return 6.1
    if word == ',':
        return -2.2
    if word in {'.', ':'}:
