        return 0.0
    if not z:
        return -0.17 if '\n' in s or '\r' in s else -0.08 if '\t' in s else 0.30
    if len(z) == 1 and z in '0123456789':
        return (0.25, 0.65, 0.88, 0.69, 0.54,
                0.59, 0.74, 0.51, 0.49, 0.27)[int(z)]
    if set(z) == {'·'}:
        return -0.66
    if set(z) == {'^'} and len(z) > 1:
        return -1.29
    if z == 'def':
        return 1.78
    if z.lstrip('#(') == 'from':
        return 1.54 if z == 'from' else 1.20
    if z in {'import', 'print', 'const'}:
        return 0.90
    if z == r'\t':
