    if low in AUXILIARIES:
        return -0.18
    if low in ARTICLES:
        return -0.08 if z[0].isupper() else 0.46 if s.startswith(' ') else 0.20
    if low in PREPOSITIONS:
        return 0.45
    if low == 'of':
        return 0.04
    if low in {'and', 'or', 'but', 'as', 'that', 'if'}:
        return 0.10
    if z in {'I', 'We'}:
        return -0.20
