"""An orthographic approximation to a Slavic n/н-fragment feature.

Inflection-like n fragments after a stem's consonant are negative, as are
consonant+n clusters and some accented adjective endings. Short vowel+n
fragments can instead be positive.
Nearby distinctive letters supply language hints, not a full language or
part-of-speech analysis. Most other tokens receive zero. Repeated middle
dots are a separate negative punctuation case.
"""
import unicodedata as ud
from functools import lru_cache

READS = ()
VOWELS = set('aeiouyаеиоуыэюяіїєё')
SLAVIC = set('ąćęłńśźżčďěňřšťůžľĺŕ')
LATIN_ENDINGS = set('n na ne ni no ny nou nym nymi nych nej nego nem '
                    'nie nia niu'.split())
CYRILLIC_ENDINGS = set('н на не ни но ны ный ний ная ное ные ной '
                       'ного ному ным ными ных ную ном нем ней них'.split())
ADJECTIVE_VOWELS = {'á', 'é', 'í', 'ý', 'ých', 'ého', 'ému', 'ým'}


@lru_cache(maxsize=16384)
def plain(text):
    # Remove Latin accents, but preserve Cyrillic letters such as й.
    return ''.join(
        ''.join(d for d in ud.normalize('NFD', c) if not ud.combining(d))
        if 'LATIN' in ud.name(c, '') else c for c in text.lower())


def predict(token, recent):
    s = plain(token)
    p = plain(recent[-1:])
    stem_length = 0
    for c in reversed(recent):
        if not c.isalpha():
            break
        stem_length += 1
    joined = s[:1].isalpha() and p.isalpha()
    consonant = p.isalpha() and p not in VOWELS
    context = recent.lower()
    if token == '··':
        return -1.33
    if any('CYRILLIC' in ud.name(c, '') for c in s):
        if s in CYRILLIC_ENDINGS:
            if joined and consonant and stem_length >= 3:
                if any(c in context for c in 'іїє'):
                    return -2.2
                if s == 'ни':
                    return -2.7
                if s == 'н' and 'ъ' in context:
                    return -3.2
                return -1.0
            return 0.28
        if s.endswith('н') and len(s.strip()) <= 4:
            if 'ен' in s:
                return -0.3
            if joined and p in set('кгх'):
                return 0.8
            if any(v + 'н' in s for v in 'аоиу'):
                return 0.2
        if s == 'і' and joined and p == 'н':
            return -1.5
        if 'нн' in s:
            return -0.5
    elif any(c in SLAVIC for c in context + token.lower()):
        if s.strip() == 'to':  # Slavic demonstrative, unlike English "to".
            return 0.95
        if s.endswith('n') and len(s.strip()) >= 2 and s[-2] in VOWELS:
            if s.endswith('en'):
                return -0.4
            return 1.2 if token.endswith('án') else 0.15
        if joined:
            if s in LATIN_ENDINGS and consonant and stem_length >= 3:
                return -3.35
            if s.endswith('n') and any(
                c == 'n' and i and s[i-1].isalpha()
                and s[i-1] not in VOWELS for i, c in enumerate(s)
            ):
                return -3.2
            if token.lower() in ADJECTIVE_VOWELS:
                if consonant and stem_length >= 3:
                    if token.lower() == 'é':
                        return -3.0 if p == 'n' else -1.6
                    if token.lower() in {'ý', 'ých'}:
                        return -2.2 if p == 'n' else -0.9
                return -1.6 if p == 'n' and stem_length >= 3 else -0.3
            if p == 'n' and s[:1] in VOWELS:
                return -0.26
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = predict(token, recent)
    return (doc, (recent + token)[-256:]), value

