READS = ()

STRONG = {"many", "two", "some", "several", "four", "five", "three", "few", "ten"}
MEDIUM = {"all", "most", "any", "both", "none", "much", "enough", "either", "neither", "lots"}
WEAK = {"each", "those", "half", "more"}
DIGITS = set("0123456789")


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    if len(tokens) < 2 or tokens[-1] != " of":
        return carry, 0.0
    if prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    word = tokens[-2].strip().lower()
    if word in STRONG or word in DIGITS:
        value = -8.0
    elif word in MEDIUM:
        value = -5.5
    elif word in WEAK:
        value = -2.0
    else:
        value = 0.0
    return carry, value

programs.sol:
"""A signed spelling-join detector, chiefly for continuations of w/v.

wab/wap-like chunks tend positive; wai/wam/wim-like chunks tend negative.
The response depends on the chunk, not just the letter w: ordinary -able
suffixes and camel-case word boundaries are excluded. Whole swap/swim
forms, several Cyrillic/Thai joins, and Chinese 'exchange' are also modeled.
These are approximate spelling rules, not a general semantic classifier.
All other tokens predict zero, and joins cannot cross document boundaries.
"""
import re
from functools import lru_cache

READS = ()


@lru_cache(maxsize=16384)
def predict(current, previous):
    s, p = current.lower(), previous.lower()
    if re.fullmatch(r'[ ._]*swap(?:s|ped|ping)?', s):
        capitalized = current.lstrip(' ._')[:1].isupper()
        return 3.93 * (1.6 if capitalized else 1.0)
    if s.startswith('wap'):
        return 7.67
    if re.fullmatch(r' swim(?:s|ming|mer|mers)?', s):
        return -0.88
    if current == '交换':  # exchange / swap
        return 2.99
    if p.endswith('ว'):
        if s.startswith('ัน'):  # completes Thai วัน, day
            return 8.12
        if s.startswith(('่า', 'าย', 'เว')):
            return -1.78
    if not s or s[0].isspace():
        return 0.0
    if p.endswith('в'):  # Cyrillic v
        if s.startswith('ай'):
            gain = 1.4 if p.endswith('ав') else 1.0
            return -4.24 * gain * (0.4 if s.startswith('айд') else 1.0)
        return {'об': 4.61, 'оп': 1.07, 'ум': -2.56}.get(s, 0.0)

    # Lowercase-to-titlecase joins usually start a new identifier word.
    if current[:1].isupper() and not current.isupper():
        if len(previous.strip()) > 1 and previous[-1:].islower():
            return 0.0
    if p.endswith('u'):
        return {'am': -3.44, 'ane': -6.37}.get(s, 0.0)
    if p.endswith(('wa', 'va')):
        s = 'a' + s
    elif not p.endswith(('w', 'v')):
        return 0.0
    gain = 0.6 if p.endswith(('v', 'va')) else 1.0

    # Positive wa-like spelling completions; -able and waffle differ.
    if s.startswith('ab') and not s.startswith('abl'):
        return 5.51 * gain * (1.0 if len(s) == 2 else 0.45)
    if s.startswith('ap') and not s.startswith('apor'):
        short_chunk = s[:3] == 'app' or len(s) < 3 or s == 'aps'
        return 7.40 * gain * (1.0 if short_chunk else 0.4)
    if s == 'ac' or s.startswith('acc'):
        return 1.94 * gain * (1.5 if current.isupper() else 1.0)
    if s.startswith('af') and not s.startswith('affl'):
        return 2.92 * gain * (0.6 if s == 'af' else 1.0)

    # Negative vowel/nasal chunks, strongest for wain and extended wam.
    if s.startswith('ain'):
        return -7.92 * gain * (1.2 if p.endswith('sw') else 1.0)
    if s == 'ai':
        return -4.03 * gain
    if s.startswith('am'):
        if s.startswith(('ame', 'ami', 'amy')):
            gain *= 2.0
        elif s.startswith('ampl'):
            gain *= 0.55
        return -1.90 * gain
    if s.startswith('im') and not s.startswith('imp'):
        return -2.07 * gain
    if s.startswith('em'):
        return -0.78 * gain
    if s.startswith('ob'):
        return 1.21 * gain
    for onset, value in [('ubb', 2.84), ('under', 2.04),
                         ('etter', 3.45), ('ight', -2.27)]:
        if s.startswith(onset):
            return value * gain
    return 0.0


def step(carry, prefix, upstream):
    previous = ''
    if (prefix.position and
            prefix.document_ids[-1] == prefix.document_ids[-2]):
        previous = prefix.token_strings[-2]
    return None, predict(prefix.token_strings[-1], previous)
